/* Setiap percobaan memiliki gambar proses, pengamatan, asumsi, dan penalaran tersendiri.
   Seluruh angka dalam model ialah contoh ideal/ilustratif, bukan hasil pengukuran nyata. */
(()=>{'use strict';
const M={};
const add=(id,opts)=>M[id]={id,...opts};
const n=(x,d=2)=>Number(x).toLocaleString('id-ID',{maximumFractionDigits:d});
const v=(o,k)=>+o[k];
const esc=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const text=(x,y,s,cls='note',extra='')=>`<text x="${x}" y="${y}" class="${cls}" ${extra}>${esc(s)}</text>`;
const line=(x1,y1,x2,y2,color='#4b8b76',width=3,extra='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="${width}" stroke-linecap="round" ${extra}/>`;
const arrow=(x1,y1,x2,y2,color='#d8895c',width=4)=>{const a=Math.atan2(y2-y1,x2-x1),L=12;return `<path d="M${x1} ${y1}L${x2} ${y2}M${x2-L*Math.cos(a-.48)} ${y2-L*Math.sin(a-.48)}L${x2} ${y2}L${x2-L*Math.cos(a+.48)} ${y2-L*Math.sin(a+.48)}" stroke="${color}" stroke-width="${width}" fill="none" stroke-linecap="round" stroke-linejoin="round"/>`};
const circ=(x,y,r,color,stroke='none',w=2)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${color}" stroke="${stroke}" stroke-width="${w}"/>`;
const rect=(x,y,w,h,fill,rx=10,stroke='none',sw=2)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}" fill="${fill}" stroke="${stroke}" stroke-width="${sw}"/>`;
const svg=(inner,label='Model percobaan sains')=>`<svg class="scene" viewBox="0 0 760 340" role="img" aria-label="${esc(label)}" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arr" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8" fill="#5b9d83"/></marker><linearGradient id="water" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#c0edf1"/><stop offset="1" stop-color="#71b5da"/></linearGradient></defs>${inner}</svg>`;
const S=(id,label,min,max,step,value,unit='')=>({id,label,min,max,step,value,unit,type:'range'});
const C=(id,label,options,value)=>({id,label,options,value,type:'select'});
const grid=(x=62,y=70,w=640,h=208)=>Array.from({length:7},(_,i)=>line(x+i*w/6,y,x+i*w/6,y+h,'#e1e8dd',1)).join('')+Array.from({length:5},(_,i)=>line(x,y+i*h/4,x+w,y+i*h/4,'#e1e8dd',1)).join('');
const foreground=(caption)=>text(25,28,caption,'note');
const explain=(result,detail)=>({value:result,detail});

add('wave',{module:9,name:'Gelombang yang benar-benar bergerak',emoji:'〰️',tag:'Gelombang',
 observe:'Amati puncak, lembah, amplitudo, dan jarak antarpuncak. Titik pada tali bergetar naik-turun; bentuk gelombangnya merambat ke kanan.',
 question:'Pada medium yang sama, apa yang terjadi pada panjang gelombang ketika frekuensi dinaikkan?',
 concept:'Cepat rambat ditentukan sifat medium. Jika cepat rambat tetap, frekuensi lebih besar berarti lebih banyak gelombang lewat tiap detik, sehingga panjang gelombang mengecil.',
 derivation:['Satu gelombang berpindah sejauh satu panjang gelombang (λ) selama satu periode (T).','Karena v = jarak/waktu, maka v = λ/T.','Frekuensi f = 1/T, sehingga v = f × λ. Untuk medium yang sama: λ = v/f.'],
 assumption:'Gelombang transversal sinusoidal ideal; medium tidak berubah. Gerakan ditampilkan lebih lambat agar tampak jelas. Grafik posisi tali, bukan lintasan benda yang berjalan mengikuti gelombang.',
 controls:[S('speed','Cepat rambat medium',2,10,1,6,'m/s'),S('f','Frekuensi',1,5,.5,2,'Hz'),S('amp','Amplitudo',10,65,5,35,'satuan gambar')],
 calc:o=>explain(`λ = ${n(o.speed/o.f)} m · T = ${n(1/o.f)} s`,`Gelombang merambat ${n(o.speed)} m setiap detik. Dengan f = ${n(o.f)} Hz, jarak antarpuncak = ${n(o.speed)} ÷ ${n(o.f)} = ${n(o.speed/o.f)} m.`),
 render:(o,t)=>{let lam=o.speed/o.f,lamPx=lam*60;const x0=73,y0=174,A=o.amp;const phase=t*.22;let pts=[];for(let x=75;x<=698;x+=3){const y=y0-A*Math.sin(2*Math.PI*((x-75)/lamPx-o.f*phase));pts.push(`${x.toFixed(1)},${y.toFixed(1)}`)}const crest=75+((lamPx*(.25+o.f*phase))%lamPx);return svg(grid()+line(66,y0,700,y0,'#acbdba',2,'stroke-dasharray="7 7"')+`<polyline points="${pts.join(' ')}" fill="none" stroke="#3a947e" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/>`+arrow(75,53,75+lamPx,53,'#da965c',3)+arrow(75+lamPx,53,75,53,'#da965c',3)+text(75+lamPx/2,42,`λ = ${n(lam)} m`,'note','text-anchor="middle"')+line(crest,y0,crest,y0-A,'#bc7cbd',3)+circ(crest,y0-A,5,'#bc7cbd')+text(crest+(crest>600?-65:15),y0-A/2,`A = ${n(A)}`,'tiny')+arrow(470,291,610,291,'#438c77',4)+text(540,315,'arah rambat →','tiny','text-anchor="middle"')+text(540,95,`f = ${n(o.f)} Hz`,'note')+text(540,115,`v = ${n(o.speed)} m/s`,'tiny'), 'Gelombang transversal sinusoidal merambat ke kanan dengan panjang gelombang dan amplitudo terukur');}
});

add('oscillation',{module:9,name:'Menghitung getaran',emoji:'⏱️',tag:'Getaran',
 observe:'Bola pegas berulang kali bergerak melalui titik setimbang. Satu getaran berarti kembali ke posisi dan arah gerak semula.',
 question:'Jika jumlah getaran sama, apakah frekuensinya naik atau turun ketika waktu pengamatan diperpanjang?',
 concept:'Frekuensi menghitung siklus per detik, sementara periode mengukur waktu per siklus. Keduanya saling berkebalikan.',
 derivation:['n getaran tercatat dalam waktu t, maka jumlah getaran tiap detik adalah f = n/t.','Waktu yang diperlukan untuk satu getaran adalah T = t/n.','Perhatikan hubungan f = 1/T.'],
 assumption:'Model osilasi harmonik ideal dengan frekuensi yang disetel dari data pengamatan; gerak di layar diperlambat.',
 controls:[S('cycles','Banyak getaran',5,80,5,40,'kali'),S('duration','Waktu pengamatan',2,40,2,20,'s')],
 calc:o=>explain(`f = ${n(o.cycles/o.duration)} Hz · T = ${n(o.duration/o.cycles)} s`,`${o.cycles} getaran ÷ ${o.duration} s = ${n(o.cycles/o.duration)} getaran per detik.`),
 render:(o,t)=>{const f=o.cycles/o.duration;const x=385+130*Math.sin(2*Math.PI*f*t*.25);return svg(foreground('Getaran dan titik setimbang')+line(160,225,610,225,'#cad8cf',4)+line(385,94,385,268,'#b5bcbc',2,'stroke-dasharray="6 7"')+`<path d="M${220} 190 ${Array.from({length:18},(_,i)=>`L${230+i*8} ${i%2?202:178}`).join(' ')} L${x-30} 190" stroke="#7cae9a" stroke-width="4" fill="none"/>`+circ(x,190,27,'#f4c47d','#876d55',3)+text(385,294,'titik setimbang','tiny','text-anchor="middle"')+text(80,74,`f = ${n(f)} Hz`,'note')+text(80,99,`T = ${n(1/f)} s`,'note')+text(470,72,'← satu siklus →','tiny'))}
});

add('reflection',{module:9,name:'Sudut datang dan sudut pantul',emoji:'🪞',tag:'Cahaya',
 observe:'Arah sinar datang dan sinar pantul simetris terhadap garis normal, bukan terhadap permukaan cermin.',
 question:'Jika sudut datang 30° terhadap normal, berapa sudut pantulnya?',
 concept:'Hukum pemantulan: sudut datang = sudut pantul, keduanya diukur dari garis normal yang tegak lurus permukaan cermin.',
 derivation:['Tarik garis normal tepat di titik sinar mengenai cermin.','Ukur sudut datang dari normal.','Menurut hukum pemantulan, sudut pantul i = r. Jika sudut diberikan terhadap permukaan, ubah dulu: i = 90° − sudut terhadap permukaan.'],
 assumption:'Cermin datar ideal dan sinar berada dalam satu bidang.',
 controls:[S('angle','Sudut terhadap garis normal',0,80,5,30,'°')],
 calc:o=>explain(`Sudut pantul = ${o.angle}°`,`Sudut datang ${o.angle}° dari normal, sehingga sudut pantul juga ${o.angle}°. Terhadap permukaan, sudutnya ${90-o.angle}°.`),
 render:(o,t)=>{const a=o.angle*Math.PI/180;const x=390,y=220,d=155;return svg(foreground('Sudut selalu diukur dari normal')+rect(100,225,570,17,'#bfd6d0',1)+line(100,225,680,225,'#466f66',4)+line(x,35,x,260,'#899d95',2,'stroke-dasharray="6 7"')+arrow(x-Math.sin(a)*d,y-Math.cos(a)*d,x,y,'#db9862',4)+arrow(x,y,x+Math.sin(a)*d,y-Math.cos(a)*d,'#4a9db0',4)+text(390,51,'normal','tiny','text-anchor="middle"')+text(126,259,'cermin','tiny')+text(190,100,'datang','note')+text(530,101,'pantul','note')+text(335,188,`i = ${o.angle}°`,'tiny')+text(421,188,`r = ${o.angle}°`,'tiny'), 'Sinar datang dan pantul simetris terhadap garis normal');}
});

add('refraction',{module:9,name:'Cahaya berbelok saat membias',emoji:'🔎',tag:'Cahaya',
 observe:'Ganti medium asal dan medium tujuan. Jika cahaya masuk medium dengan indeks bias lebih tinggi, arahnya mendekati normal; jika keluar menuju indeks bias lebih rendah, menjauhi normal.',
 question:'Apa yang terjadi pada sinar dari air ke udara? Dapatkah pada sudut besar sinar tidak menembus keluar?',
 concept:'Cepat rambat cahaya berubah saat melewati batas medium. Hukum Snell: n₁ sin i = n₂ sin r. Pada arah indeks tinggi ke indeks rendah, ada sudut kritis yang dapat menyebabkan pemantulan internal total.',
 derivation:['Indeks bias n = c/v menyatakan perbandingan cepat cahaya ruang hampa terhadap cepatnya dalam medium.','Gunakan n₁ sin i = n₂ sin r, dengan i dan r diukur terhadap garis normal.','Untuk n₁ > n₂ dan sin r yang diperlukan lebih besar dari 1, tidak ada sinar bias merambat keluar: terjadi pemantulan internal total.'],
 assumption:'Dua medium transparan, homogen, batas datar, tanpa rugi energi pada model. Warna area hanya penanda medium dan tidak berskala.',
 controls:[S('angle','Sudut datang dari normal',0,80,5,45,'°'),C('from','Medium asal',[['1','Udara (n = 1)'],['1.33','Air (n = 1,33)'],['1.5','Kaca (n = 1,50)']],'1'),C('index','Medium tujuan',[['1.33','Air (n = 1,33)'],['1.5','Kaca (n = 1,50)'],['1','Udara (n = 1)']],'1.5')],
 calc:o=>{const n1=+o.from,n2=+o.index,k=n1*Math.sin(o.angle*Math.PI/180)/n2;if(k>1.000001)return explain('Pemantulan internal total',`n₁ sin i / n₂ = ${n(k,3)} > 1, sehingga tidak ada sudut bias nyata. Ini hanya bisa terjadi dari indeks bias lebih tinggi menuju lebih rendah.`);let r=Math.asin(Math.min(1,k))*180/Math.PI;return explain(`Sudut bias ≈ ${n(r,1)}°`,`sin r = (${n(n1)} ÷ ${n(n2)}) × sin ${o.angle}°. Maka r ≈ ${n(r,1)}° dari garis normal.`)},
 render:(o,t)=>{const n1=+o.from,n2=+o.index,a=o.angle*Math.PI/180,k=n1*Math.sin(a)/n2,full=k>1.000001,b=Math.asin(Math.min(1,k)),x=390,y=166,d=150;
  const fills={'1':'#f5f3e9','1.33':'#c5e6ee','1.5':'#d5e5f5'};
  return svg(rect(60,32,640,130,fills[o.from],0)+rect(60,171,640,132,fills[o.index],0)+line(60,166,700,166,'#8baba7',4)+line(x,40,x,294,'#96aba1',2,'stroke-dasharray="6 6"')+arrow(x-Math.sin(a)*d,y-Math.cos(a)*d,x,y,'#d98c5c',4)+(full?arrow(x,y,x+Math.sin(a)*d,y-Math.cos(a)*d,'#509ab0',4):arrow(x,y,x+Math.sin(b)*d,y+Math.cos(b)*d,'#509ab0',4))+text(71,61,`asal n₁ = ${n(n1)}`,'note')+text(71,221,`tujuan n₂ = ${n(n2)}`,'note')+text(420,121,`i = ${o.angle}°`,'tiny')+text(420,246,full?'Tidak ada sinar bias':`r ≈ ${n(b*180/Math.PI,1)}°`,'tiny'),'Pembiasan dari medium asal ke medium tujuan sesuai hukum Snell, termasuk pemantulan internal total');}
});

add('lever',{module:6,name:'Tuas dan titik tumpu',emoji:'⚖️',tag:'Pesawat sederhana',
 observe:'Lihat titik tumpu, posisi beban dan kuasa, serta arah gaya. Yang menentukan keseimbangan adalah gaya × lengan tegak lurus.',
 question:'Jika titik kuasa digeser makin jauh dari tumpu sementara beban tetap, berapa gaya minimal agar seimbang?',
 concept:'Tuas setimbang jika jumlah momen gaya searah jarum jam sama dengan momen berlawanan arah: W × lᵦ = F × lₖ.',
 derivation:['Momen gaya adalah τ = F × l dengan l jarak tegak lurus dari titik tumpu ke garis kerja gaya.','Ketika setimbang, momen kiri = momen kanan.','Karena Wlᵦ = Flₖ, diperoleh F = Wlᵦ/lₖ. Lengan kuasa lebih panjang berarti gaya yang dibutuhkan lebih kecil.'],
 assumption:'Batang dianggap ringan, tumpu tanpa gesekan, gaya vertikal, kondisi statis. Kemiringan pada gambar memperlihatkan kecenderungan putaran secara ilustratif, bukan dinamika waktu nyata.',
 controls:[S('load','Berat beban',40,240,20,100,'N'),S('left','Lengan beban',10,50,5,20,'cm'),S('right','Lengan kuasa',20,100,5,50,'cm'),S('force','Gaya kuasa yang diberikan',10,160,5,40,'N')],
 calc:o=>{const req=o.load*o.left/o.right,diff=o.load*o.left-o.force*o.right;return explain(`${Math.abs(diff)<1?'Seimbang':'Belum seimbang'} · F perlu ${n(req)} N`,`Momen beban = ${o.load} × ${o.left} = ${n(o.load*o.left)} N·cm. Momen kuasa = ${o.force} × ${o.right} = ${n(o.force*o.right)} N·cm.`)},
 render:(o,t)=>{let k=2.7,x=360,y=179,imb=(o.load*o.left-o.force*o.right)/10000,angle=Math.max(-.12,Math.min(.12,imb)),l=o.left*k,r=o.right*k;return svg(foreground('Beban di kiri • kuasa di kanan')+`<g transform="translate(${x} ${y}) rotate(${angle*180/Math.PI})">`+line(-l-10,0,r+10,0,'#ab906f',15)+arrow(-l,-95,-l,-13,'#d88862',5)+arrow(r,-95,r,-13,'#4b9b82',5)+circ(-l,0,10,'#c8835a')+circ(r,0,10,'#5f988b')+text(-l-32,-106,`${o.load} N`,'note')+text(r-32,-106,`${o.force} N`,'note')+line(-l,20,0,20,'#d88862',2)+line(0,29,r,29,'#4b9b82',2)+text(-l/2,43,`${o.left} cm`,'tiny','text-anchor="middle"')+text(r/2,43,`${o.right} cm`,'tiny','text-anchor="middle"')+'</g>'+`<path d="M${x-22} ${y+32}L${x+22} ${y+32}L${x} ${y+4}Z" fill="#e4b86e" stroke="#977e58" stroke-width="3"/>`+text(360,292,'titik tumpu','tiny','text-anchor="middle"'), 'Tuas bertumpu di tengah, beban dan kuasa di lengan berlawanan');}
});

add('pulley',{module:6,name:'Katrol: gaya dan panjang tarikan',emoji:'🪢',tag:'Pesawat sederhana',
 observe:'Hitung ruas tali yang langsung menopang beban. Makin banyak ruas penopang, makin kecil tarikan, tetapi tali yang ditarik makin panjang.',
 question:'Beban 200 N disangga empat ruas tali ideal. Berapa gaya tarik dan panjang tali yang ditarik untuk mengangkatnya 1 m?',
 concept:'Pada tali ideal, tegangan di setiap ruas sama. Jika n ruas menopang satu beban, jumlah gaya ke atas nF = W.',
 derivation:['Tegangan tali ideal merata, sebesar F pada setiap ruas.','Dengan n ruas penopang: nF = W, sehingga F = W/n.','Kekekalan kerja ideal: F × s = W × h; jadi s = n × h. Penghematan gaya ditukar dengan jarak tarikan.'],
 assumption:'Sistem katrol ideal tanpa gesekan dan tanpa berat tali/katrol. Ruas tegak yang ditampilkan adalah skema gaya penopang, bukan penggambaran lengkap lintasan satu tali.',
 controls:[S('load','Berat beban',80,320,40,200,'N'),C('strands','Ruas tali penopang', [['1','1 ruas (katrol tetap)'],['2','2 ruas (katrol bergerak)'],['4','4 ruas (katrol majemuk)']],'2'),S('height','Kenaikan beban',.5,2,.5,1,'m')],
 calc:o=>{let k=+o.strands;return explain(`Gaya = ${n(o.load/k)} N · tali = ${n(k*o.height)} m`,`F = ${o.load} ÷ ${k} = ${n(o.load/k)} N. Agar beban naik ${n(o.height)} m, tarik tali ${n(k*o.height)} m.`)},
 render:(o,t)=>{const k=+o.strands,x=215,yTop=100,yBottom=242,gap=k===1?1:k===2?55:39;let ropes='';for(let i=0;i<k;i++){const xx=x+(i-(k-1)/2)*gap;ropes+=line(xx,yTop+20,xx,yBottom-21,'#ae8a5c',5)+circ(xx,yTop+20,8,'#eee2c7','#a98a5b',2)}return svg(foreground('Setiap ruas tali menyumbang gaya ke atas')+rect(75,71,365,16,'#bdcfc9',2)+ropes+rect(130,225,170,57,'#f1c68c',8,'#b58356',3)+text(215,257,`${o.load} N`,'note','text-anchor="middle"')+text(465,136,`${k} ruas penopang`,'note')+text(465,170,`F = ${n(o.load/k)} N`,'note')+arrow(380,237,380,165,'#3d9d87',5)+text(467,213,`Beban naik ${n(o.height)} m`,'tiny')+text(467,239,`Tarik tali ${n(k*o.height)} m`,'tiny')+text(85,308,'skema gaya · bukan gambar rangkaian tali lengkap','tiny'), 'Skema jumlah ruas tali penopang beban katrol, jumlah gaya seimbang');}
});

add('incline',{module:6,name:'Bidang miring dan usaha',emoji:'📐',tag:'Pesawat sederhana',
 observe:'Pada papan yang lebih panjang untuk kenaikan ketinggian sama, gaya dorong sejajar papan berkurang. Jarak yang ditempuh justru lebih jauh.',
 question:'Mengapa bidang miring tidak menciptakan energi meskipun gaya yang diperlukan lebih kecil?',
 concept:'Pada bidang miring licin, kerja input F × L sama dengan pertambahan energi potensial W × h.',
 derivation:['Kerja ideal sepanjang papan = F × L.','Untuk menaikkan beban dengan berat W setinggi h, energi potensial bertambah W × h.','Karena FL = Wh, F = W(h/L) dan keuntungan mekanik ideal = L/h.'],
 assumption:'Gerak pelan/kelajuan tetap, papan licin dan ideal; W adalah berat dalam newton, bukan massa dalam kg. Tinggi h tidak boleh melebihi panjang L.',
 controls:[S('weight','Berat beban',100,400,50,300,'N'),S('length','Panjang papan',3,10,1,6,'m'),S('height','Tinggi vertikal',.5,2.5,.5,2,'m')],
 calc:o=>explain(`F = ${n(o.weight*o.height/o.length)} N · KM = ${n(o.length/o.height)}`,`Usaha menaikkan beban = W × h = ${n(o.weight*o.height)} J. F × ${o.length} = ${n(o.weight*o.height)} J, sehingga F = ${n(o.weight*o.height/o.length)} N.`),
 render:(o,t)=>{const x=120,y=267,L=490,dx=L*Math.sqrt(1-(o.height/o.length)**2),dy=L*o.height/o.length,xe=x+dx,ye=y-dy;const p=.45;const bx=x+(xe-x)*p,by=y+(ye-y)*p;return svg(line(x,y,690,y,'#c1d7ba',5)+`<path d="M${x} ${y}L${xe} ${ye}L${xe} ${y}Z" fill="#e7d8b7" stroke="#c2b18f" stroke-width="2"/>`+line(x,y,xe,ye,'#a68d69',9)+rect(bx-27,by-43,57,42,'#edae78',5,'#ae794c',3)+arrow(bx+35,by-19,bx+90*(dx/L),by-19-90*(dy/L),'#459a82',4)+line(xe,ye,xe,y,'#c47775',2,'stroke-dasharray="7 5"')+text(xe+11,(ye+y)/2,`h = ${n(o.height)} m`,'tiny')+text(260,220,`L = ${n(o.length)} m`,'note')+text(72,67,`F ideal = ${n(o.weight*o.height/o.length)} N`,'note')+text(72,91,`Berat = ${o.weight} N`,'tiny'),'Bidang miring dengan panjang papan L, tinggi h, dan balok ditarik sejajar permukaan');}
});

add('newton',{module:6,name:'Troli: resultan gaya dan percepatan',emoji:'🛒',tag:'Gerak',
 observe:'Panah yang berlawanan arah harus dikurangkan. Troli dipercepat oleh resultan gaya, bukan hanya oleh gaya dorong.',
 question:'Troli bermassa dua kali lebih besar, tetapi resultan gaya tetap. Bagaimana percepatannya?',
 concept:'Hukum II Newton: resultan gaya luar ΣF = ma. Arah percepatan sama dengan arah resultan gaya.',
 derivation:['Tetapkan kanan sebagai arah positif.','Resultan gaya = gaya dorong − gaya gesek, jika gesekan ke kiri.','Dari ΣF = ma, maka a = (F dorong − F gesek)/m. Jika resultan sama, massa dua kali memberi percepatan setengah.'],
 assumption:'Gerak satu dimensi, massa tetap, gesekan ditetapkan sebagai gaya yang berlawanan arah gerak, g = 10 m/s² tidak diperlukan untuk contoh ini.',
 controls:[S('drive','Gaya ke kanan',10,80,5,30,'N'),S('friction','Gaya gesek ke kiri',0,30,5,10,'N'),S('mass','Massa troli',1,10,1,5,'kg')],
 calc:o=>explain(`ΣF = ${o.drive-o.friction} N · a = ${n((o.drive-o.friction)/o.mass)} m/s²`,`Gaya kanan ${o.drive} N dikurangi gaya kiri ${o.friction} N, dibagi massa ${o.mass} kg.`),
 render:(o,t)=>{const a=(o.drive-o.friction)/o.mass,tx=120+Math.min(405,.5*Math.max(a,0)*((t*.8)%4)**2*6);return svg(foreground('Panah menunjukkan gaya, bukan kecepatan')+line(55,269,696,269,'#a8bcb1',4)+rect(tx,183,140,68,'#a9dbc5',12,'#59897a',3)+circ(tx+28,259,20,'#546e69')+circ(tx+115,259,20,'#546e69')+arrow(tx+145,210,tx+145+Math.min(190,o.drive*2),210,'#4b9c7d',5)+(o.friction>0?arrow(tx-5,231,tx-5-Math.min(160,o.friction*3),231,'#da8b69',5):'')+text(64,66,`F kanan = ${o.drive} N`,'note')+text(64,91,`F gesek = ${o.friction} N`,'tiny')+text(470,71,`a = ${n(a)} m/s²`,'note'),'Troli di permukaan datar dipercepat oleh selisih gaya dorong dan gesek');}
});

add('speed',{module:6,name:'Jarak, waktu, dan kelajuan',emoji:'🚴',tag:'Gerak',
 observe:'Penanda bergerak di lintasan yang sama. Kelajuan rata-rata diperoleh dari seluruh jarak dibagi seluruh waktu, bukan dari titik akhir saja.',
 question:'Jika jarak tetap 1.200 m tetapi waktu tempuh berkurang setengah, bagaimana kelajuannya?',
 concept:'Kelajuan rata-rata = total jarak ditempuh / total durasi. Satuan harus disamakan sebelum membagi.',
 derivation:['Definisi kelajuan rata-rata: v = s/t.','Jika t dalam menit, kalikan 60 untuk memperoleh detik.','Contoh: s = 1.200 m, t = 4 menit = 240 s, maka v = 5 m/s.'],
 assumption:'Simulasi menunjukkan gerak berkelajuan konstan sebagai contoh, bukan seluruh gerakan di dunia nyata.',
 controls:[S('distance','Jarak tempuh',200,2000,100,1200,'m'),S('duration','Waktu tempuh',40,400,20,240,'s')],
 calc:o=>explain(`v = ${n(o.distance/o.duration)} m/s`,`Jarak ${n(o.distance)} m ÷ waktu ${n(o.duration)} s = ${n(o.distance/o.duration)} m/s.`),
 render:(o,t)=>{const fraction=((t*.15)%1),x=97+fraction*560;return svg(foreground('Jarak yang sama ditempuh dengan durasi berbeda')+line(85,250,678,250,'#c1b596',14)+Array.from({length:7},(_,i)=>rect(91+i*88,246,30,5,'#fff8df',2)).join('')+circ(x,222,18,'#334f49')+circ(x+45,222,18,'#334f49')+line(x,222,x+26,188,'#7d9a9d',4)+line(x+26,188,x+45,222,'#7d9a9d',4)+line(x+45,222,x,222,'#7d9a9d',3)+circ(x+25,163,12,'#f1b88c')+line(x+26,175,x+26,191,'#715c63',5)+text(85,81,`s = ${n(o.distance)} m`,'note')+text(85,110,`t = ${n(o.duration)} s`,'note')+text(460,86,`v = ${n(o.distance/o.duration)} m/s`,'note')+text(93,286,'mulai','tiny')+text(655,286,'akhir','tiny'),'Pesepeda menempuh lintasan lurus dari awal ke akhir');}
});

add('density',{module:7,name:'Mengapung atau tenggelam?',emoji:'🧊',tag:'Fluida',
 observe:'Benda yang kurang rapat daripada air mengapung. Bagian terendam berubah mengikuti perbandingan massa jenis benda terhadap cairan.',
 question:'Apakah benda bermassa besar selalu tenggelam? Bandingkan dengan volume dan massa jenis.',
 concept:'Massa jenis ρ = m/V. Di fluida diam, gaya apung setara berat fluida yang dipindahkan (prinsip Archimedes). Untuk benda mengapung, fraksi volume terendam = ρbenda/ρcair.',
 derivation:['Massa jenis: ρ = m/V.','Gaya apung = ρcair × g × Vterendam; berat benda = ρbenda × g × Vbenda.','Jika terapung setimbang, kedua gaya sama → Vterendam/Vbenda = ρbenda/ρcair.'],
 assumption:'Benda homogen, bentuk teratur, cairan diam, tidak ada gelembung dan tegangan permukaan diabaikan. Pada massa jenis sama, benda dapat melayang netral.',
 controls:[S('rho','Massa jenis benda',200,1800,100,800,'kg/m³'),S('water','Massa jenis cairan',800,1200,100,1000,'kg/m³')],
 calc:o=>{const ratio=o.rho/o.water;return explain(ratio<1?`Terapung · ${n(ratio*100)}% terendam`:ratio===1?'Melayang netral':'Tenggelam',`Perbandingan massa jenis = ${o.rho} ÷ ${o.water} = ${n(ratio)}. ${ratio<1?'Volume terendam saat seimbang adalah '+n(ratio*100)+'%.':ratio>1?'Gaya apung maksimum tidak cukup untuk menahan berat benda.':'Berat sama dengan gaya apung jika seluruh benda terendam.'}`)},
 render:(o,t)=>{let ratio=o.rho/o.water,waterline=163,h=88,bottom=ratio<1?waterline+h*ratio:ratio===1?waterline+57:277,top=bottom-h;return svg(foreground('Bandingkan massa jenis, bukan massa saja')+rect(92,84,550,220,'#eff7f8',6,'#a3cbd0',3)+rect(95,163,544,138,'url(#water)',0)+line(95,163,638,163,'#5caac5',4)+rect(317,top,110,88,'#f5c47b',8,'#b58950',3)+text(372,top+48,'BENDA','note','text-anchor="middle"')+arrow(457,119,457,155,'#d18d6d',4)+arrow(487,218,487,180,'#3d9689',4)+text(503,129,'berat ↓','tiny')+text(503,216,'gaya apung ↑','tiny')+text(110,137,`ρ cair = ${o.water}`,'note')+text(110,190,`ρ benda = ${o.rho}`,'note'),'Benda berbentuk balok terapung, melayang, atau tenggelam sesuai massa jenisnya');}
});

add('hydro',{module:7,name:'Tekanan bertambah di kedalaman',emoji:'🌊',tag:'Fluida',
 observe:'Amati panah tekanan pada satu titik di dalam air. Semakin dalam, semakin besar tekanan akibat berat cairan di atas titik tersebut.',
 question:'Jika kedalaman naik dua kali dalam cairan yang sama, bagaimana tekanan hidrostatis relatif permukaan?',
 concept:'Tekanan hidrostatis bergantung pada ρ, g, dan kedalaman h. Bentuk wadah tidak menentukan tekanan pada kedalaman yang sama.',
 derivation:['Bayangkan kolom air dengan luas penampang A dan tinggi h.','Massa kolom: m = ρAh. Beratnya mg = ρAhg.','Tekanan karena kolom itu p = F/A = ρAhg/A = ρgh.'],
 assumption:'ρ tetap, fluida diam, g = 10 m/s², tekanan yang ditampilkan adalah tekanan hidrostatis (gauge), bukan tekanan absolut termasuk tekanan atmosfer.',
 controls:[S('rho','Massa jenis fluida',800,1200,100,1000,'kg/m³'),S('depth','Kedalaman titik',.5,5,.5,2,'m')],
 calc:o=>explain(`p = ${n(o.rho*10*o.depth)} Pa`,`p = ${o.rho} × 10 × ${n(o.depth)} = ${n(o.rho*10*o.depth)} Pa. Pada kedalaman dua kali, p juga dua kali.`),
 render:(o,t)=>{let y=95+o.depth/5*205,w=35+o.depth*16;return svg(rect(110,90,400,218,'url(#water)',4,'#7eb8bf',3)+text(120,75,'permukaan','tiny')+line(110,91,510,91,'#80b6c7',3)+line(330,91,330,y,'#e6f7fa',3,'stroke-dasharray="6 6"')+circ(330,y,7,'#275b6d')+arrow(337,y,337+w,y,'#d87863',6)+text(350+w,y-11,`p = ${n(o.rho*10*o.depth)} Pa`,'note')+text(342,(y+91)/2,`h = ${n(o.depth)} m`,'tiny')+text(136,285,`ρ = ${o.rho} kg/m³`,'note'),'Tekanan hidrostatis pada kedalaman h dalam wadah cairan');}
});

add('pascal',{module:7,name:'Dongkrak hidrolik',emoji:'🛠️',tag:'Fluida',
 observe:'Dua piston luasnya berbeda terhubung cairan yang sama. Tekanan tambahan diteruskan sama, tetapi gaya pada piston lebar lebih besar.',
 question:'Jika gaya keluaran menjadi 10 kali lebih besar, apakah perpindahan piston keluaran juga menjadi 10 kali?',
 concept:'Hukum Pascal: kenaikan tekanan pada cairan tertutup diteruskan sama besar. F₁/A₁ = F₂/A₂. Dalam sistem ideal, A₁d₁ = A₂d₂.',
 derivation:['Tekanan tambahan p = F/A.','Karena p₁ = p₂: F₁/A₁ = F₂/A₂. Susun F₂ = F₁A₂/A₁.','Kekekalan volume cairan: A₁d₁ = A₂d₂. Gaya besar dibayar gerak keluaran lebih pendek.'],
 assumption:'Sistem hidrolik ideal, cairan tak termampatkan, piston tanpa gesekan, beda ketinggian diabaikan, perbandingan area memakai satuan yang sama.',
 controls:[S('force','Gaya piston kecil',10,100,10,50,'N'),S('small','Luas piston kecil',5,30,5,10,'cm²'),S('large','Luas piston besar',60,200,20,200,'cm²')],
 calc:o=>explain(`F₂ = ${n(o.force*o.large/o.small)} N`,`Tekanan tambahan = ${n(o.force/o.small)} N/cm² pada kedua piston. Jika piston kecil turun 10 cm, piston besar naik ${n(10*o.small/o.large)} cm.`),
 render:(o,t)=>{const w1=65+o.small*1.5,w2=135+o.large*.4;return svg(foreground('Tekanan tambahan sama pada kedua piston')+`<path d="M${210-w1/2} 170V284H${550-w2/2}V170H${550+w2/2}V300H${210+w1/2}V170Z" fill="#a9dbe7" stroke="#73b4c2" stroke-width="3"/>`+rect(210-w1/2,161,w1,19,'#819e91',3)+rect(550-w2/2,161,w2,19,'#819e91',3)+arrow(210,88,210,154,'#d88b69',5)+arrow(550,156,550,83,'#469b7e',5)+text(140,60,`F₁ = ${o.force} N`,'note')+text(478,54,`F₂ = ${n(o.force*o.large/o.small)} N`,'note')+text(210,321,`A₁ = ${o.small} cm²`,'tiny','text-anchor="middle"')+text(550,321,`A₂ = ${o.large} cm²`,'tiny','text-anchor="middle"'),'Dua piston hidrolik dengan luas berbeda terhubung cairan tertutup');}
});

add('heat',{module:10,name:'Mengapa air memerlukan kalor?',emoji:'🌡️',tag:'Suhu dan kalor',
 observe:'Air menerima energi dan suhu meningkat. Massa lebih banyak atau kenaikan suhu lebih besar memerlukan lebih banyak kalor.',
 question:'Jika massa air menjadi dua kali lebih banyak dan kenaikan suhu tetap, apakah kalor juga dua kali?',
 concept:'Kalor jenis c menunjukkan energi untuk menaikkan suhu 1 kg zat sebanyak 1°C tanpa perubahan wujud. Q = mcΔT.',
 derivation:['Definisi c = Q/(mΔT).','Kalikan kedua ruas dengan mΔT: Q = mcΔT.','Kenaikan suhu ΔT = suhu akhir − suhu awal. Pastikan massa dalam kg sesuai satuan c.'],
 assumption:'Pemanasan tanpa perubahan wujud, kalor jenis dianggap konstan, seluruh energi masuk diserap sampel (tanpa kehilangan panas). Animasi partikel hanya skematis.',
 controls:[S('mass','Massa air',.25,3,.25,2,'kg'),S('delta','Kenaikan suhu',5,50,5,10,'°C'),C('material','Zat dan kalor jenis',[['4200','Air (4.200 J/kg°C)'],['900','Aluminium (900 J/kg°C)'],['450','Besi (450 J/kg°C)']],'4200')],
 calc:o=>explain(`Q = ${n(o.mass*+o.material*o.delta)} J`,`Q = ${n(o.mass)} kg × ${n(o.material)} J/(kg·°C) × ${o.delta} °C = ${n(o.mass*+o.material*o.delta)} J.`),
 render:(o,t)=>{const hot=Math.min(1,o.delta/50);const dots=Array.from({length:45},(_,i)=>{const col=i%9,row=Math.floor(i/9),xx=231+col*30+Math.sin(t*(1+hot*4)+i)*hot*5,yy=133+row*27+Math.cos(t*(1+hot*3)+i*1.2)*hot*5;return circ(xx,yy,5,`hsl(${190-175*hot},${45+20*hot}%,${65-10*hot}%)`)}).join('');return svg(foreground('Kalor masuk → kenaikan suhu')+rect(175,99,390,184,'#edf3f1',18,'#9fb1b1',4)+rect(182,129,376,146,'#a9dce5',6)+dots+arrow(367,324,367,282,'#e8a26c',5)+text(80,65,`ΔT = ${o.delta}°C`,'note')+text(510,65,`m = ${n(o.mass)} kg`,'note')+text(245,314,'energi kalor masuk','tiny'),'Bejana berisi partikel yang bergerak dengan energi termal rata-rata yang meningkat saat dipanaskan');}
});

add('conduction',{module:10,name:'Kalor merambat melalui logam',emoji:'🥄',tag:'Perpindahan kalor',
 observe:'Ujung batang yang dekat sumber panas lebih dahulu panas. Energi menjalar melalui interaksi partikel, bukan seluruh logam berpindah tempat.',
 question:'Mengapa gagang sendok logam bisa panas meski bagian itu tidak langsung menyentuh air panas?',
 concept:'Konduksi memindahkan energi termal melalui bahan akibat perbedaan suhu. Pada logam, elektron bebas juga berperan besar mengangkut energi.',
 derivation:['Suhu berbeda menimbulkan aliran kalor dari yang lebih panas ke lebih dingin.','Pada konduksi, materi secara keseluruhan tidak ikut mengalir.','Laju konduksi dipengaruhi bahan, beda suhu, luas penampang, dan panjang batang; bukan sekadar banyaknya partikel.'],
 assumption:'Diagram kualitatif: warna dan kilau menyatakan urutan suhu relatif, bukan penyelesaian numerik persamaan kalor. Sumber panas berada di sebelah kiri.',
 controls:[S('time','Tahap pemanasan (ilustratif)',0,100,10,50,'%'),C('material','Bahan',[['metal','Logam penghantar baik'],['wood','Kayu penghantar buruk']],'metal')],
 calc:o=>explain(o.material==='metal'?'Kalor menyebar lebih cepat melalui logam':'Kalor menyebar lebih lambat melalui kayu',`Saat tahap ${o.time}%, perubahan warna menunjukkan bagian yang menerima energi. Bahan berbeda memiliki daya hantar kalor berbeda.`),
 render:(o,t)=>{const reach=o.time/100*(o.material==='metal'?1:.35);let segments='';for(let i=0;i<16;i++){const hot=Math.max(0,Math.min(1,(reach-i/16)*4));const fill=`hsl(${200-175*hot},${40+25*hot}%,${77-18*hot}%)`;segments+=rect(115+i*31,154,31,48,fill,0)}return svg(foreground('Benda tetap di tempat · energi merambat')+rect(70,125,64,120,'#f7bd7c',15)+Array.from({length:3},(_,i)=>`<path d="M${85+i*16} 170 Q${75+i*16} 138 ${87+i*16} 118" fill="none" stroke="#d67853" stroke-width="5"/>`).join('')+segments+text(78,283,'ujung panas','note')+text(546,283,'ujung dingin','note')+arrow(280,115,490,115,'#d98a5b',4)+text(335,99,'arah perpindahan kalor','tiny'),'Batang padat dengan energi kalor merambat dari sisi panas ke sisi dingin');}
});

add('convection',{module:10,name:'Mengapa air panas bergerak naik?',emoji:'♨️',tag:'Perpindahan kalor',
 observe:'Ketika air dipanaskan dari bawah, air yang lebih hangat cenderung menjadi lebih ringan per volume lalu naik; air lebih dingin turun.',
 question:'Apakah aliran konveksi terjadi pada benda padat yang tidak mengalir?',
 concept:'Konveksi adalah perpindahan kalor yang disertai perpindahan massa fluida (cairan atau gas).',
 derivation:['Pemanasan umumnya membuat fluida memuai, sehingga massa jenis berkurang.','Gaya apung mendorong fluida lebih hangat naik; fluida dingin menggantikan posisinya.','Terbentuk sirkulasi yang mengangkut energi bersama massa fluida.'],
 assumption:'Pola panah skematis untuk pemanasan dari bawah; aliran nyata bergantung geometri wadah dan kondisi fluida. Tidak semua fluida selalu menyirkulasi persis seperti gambar.',
 controls:[C('heating','Pemanas',[['on','Dinyalakan'],['off','Dimatikan']],'on')],
 calc:o=>explain(o.heating==='on'?'Ada pemanasan: arus konveksi terbentuk':'Pemanas mati: sirkulasi melemah','Perhatikan jalur air hangat di bagian tengah yang naik dan air lebih dingin di sisi wadah yang turun.'),
 render:(o,t)=>{const active=o.heating==='on';let bubbles=Array.from({length:12},(_,i)=>circ(240+i%4*82,245-(active?(t*20+i*13)%117:0),4,'#d4f2f2')).join('');return svg(foreground('Kalor ikut berpindah bersama aliran air')+rect(185,93,390,187,'#b8e3e9',15,'#7fb3c0',4)+rect(275,280,210,10,'#edb26f',3)+Array.from({length:5},(_,i)=>`<path d="M${288+i*44} 305Q${280+i*44} 288 ${288+i*44} 274" fill="none" stroke="#d88260" stroke-width="4"/>`).join('')+(active?`<path d="M300 232Q300 120 390 130Q480 135 480 233" fill="none" stroke="#458c9e" stroke-width="6" stroke-dasharray="14 8"/>`+arrow(300,222,300,145,'#d68b64',5)+arrow(480,145,480,230,'#568fbb',5):'')+bubbles+text(227,63,'air hangat naik','note')+text(467,63,'air dingin turun','note'),'Wadah air yang dipanaskan dari bawah, aliran konveksi naik di sisi panas dan turun di sisi dingin');}
});

add('states',{module:7,name:'Partikel: padat, cair, gas',emoji:'💧',tag:'Wujud benda',
 observe:'Susunan dan gerakan partikel berbeda. Padat bergetar di sekitar posisi tetap; cair dapat saling bergeser; gas menyebar memenuhi wadah.',
 question:'Saat es mencair, apakah partikelnya berubah menjadi jenis partikel lain?',
 concept:'Perubahan wujud fisik mengubah susunan/gerak partikel tetapi tidak mengubah identitas kimia zat murni (misalnya H₂O tetap H₂O).',
 derivation:['Dalam padat, partikel rapat dan kebanyakan bergetar di posisi sekitar keseimbangan.','Dalam cair, partikel tetap berdekatan tetapi dapat berpindah relatif satu sama lain.','Dalam gas, partikel bergerak lebih bebas dan secara umum jaraknya lebih renggang.'],
 assumption:'Skema partikel sangat disederhanakan; ukuran dan jarak gambar tidak sesuai skala molekul nyata. Suhu dan tekanan memengaruhi wujud.',
 controls:[C('phase','Pilih wujud',[['solid','Padat'],['liquid','Cair'],['gas','Gas']],'solid')],
 calc:o=>explain(({solid:'Partikel rapat, bergetar',liquid:'Partikel rapat, dapat bergeser',gas:'Partikel bergerak lebih bebas'})[o.phase],'Saat perubahan wujud fisik, zat yang sama hanya berubah penataan dan energinya.'),
 render:(o,t)=>{let dots='';for(let i=0;i<42;i++){let x,y;if(o.phase==='solid'){x=203+(i%7)*46+Math.sin(t*4+i)*2;y=96+Math.floor(i/7)*30+Math.cos(t*5+i)*2}else if(o.phase==='liquid'){x=195+(i%7)*49+Math.sin(t*1.2+i*.7)*10;y=155+Math.floor(i/7)*25+Math.cos(t*.7+i)*7}else{x=174+((i*79+t*16)%430);y=68+((i*113+t*13)%235)}dots+=circ(x,y,10,o.phase==='gas'?'#d1abce':o.phase==='solid'?'#73b9aa':'#85bccc','#4a908d',1)}return svg(foreground('Susunan partikel H₂O pada tiga wujud')+rect(127,55,500,250,'#f2f7f3',12,'#b6d2cb',4)+dots+text(314,324,({solid:'PADAT',liquid:'CAIR',gas:'GAS'})[o.phase],'note','text-anchor="middle"'),'Partikel zat dalam susunan padat, cair atau gas disertai gerakan ilustratif');}
});

add('ohm',{module:8,name:'Listrik: baterai, arus, hambatan',emoji:'🔋',tag:'Listrik',
 observe:'Arus konvensional mengalir dari terminal positif menuju negatif di rangkaian luar. Baterai memberikan tegangan, resistor menghambat arus.',
 question:'Saat hambatan dinaikkan tetapi tegangan dijaga sama, apa yang terjadi dengan arus?',
 concept:'Resistor ohmik: V = IR, sehingga I = V/R. Pada V yang sama, R lebih besar berarti I lebih kecil.',
 derivation:['Untuk resistor ohmik, perbandingan tegangan dan arus konstan: R = V/I.','Susun ulang: V = IR dan I = V/R.','Satuan: volt ÷ ohm = ampere.'],
 assumption:'Rangkaian DC tertutup ideal; baterai dianggap sumber tegangan tetap, hambatan kawat dan sumber diabaikan. Titik yang bergerak menggambarkan arah arus konvensional, bukan kecepatan sebenarnya elektron.',
 controls:[S('voltage','Tegangan baterai',3,24,1,12,'V'),S('resistance','Hambatan',2,18,1,6,'Ω')],
 calc:o=>explain(`I = ${n(o.voltage/o.resistance)} A`,`Arus = ${o.voltage} V ÷ ${o.resistance} Ω = ${n(o.voltage/o.resistance)} A. Pada tegangan tetap, arus berbanding terbalik dengan hambatan.`),
 render:(o,t)=>{const x=190,y=105,w=390,h=164;const path=`M${x} ${y}H${x+w}V${y+h}H${x}V${y}`;let q='';for(let k=0;k<4;k++){const dist=((t*.06*(o.voltage/o.resistance)+k/4)%1)*2*(w+h);let xx,yy;if(dist<w){xx=x+dist;yy=y}else if(dist<w+h){xx=x+w;yy=y+(dist-w)}else if(dist<2*w+h){xx=x+w-(dist-w-h);yy=y+h}else{xx=x;yy=y+h-(dist-2*w-h)}q+=circ(xx,yy,6,'#d5926a')};return svg(foreground('Arus konvensional: + → − lewat luar baterai')+`<path d="${path}" fill="none" stroke="#6b9d8c" stroke-width="6"/>`+rect(366,84,79,42,'#f3d398',6,'#b88b53',3)+text(383,110,`${o.resistance} Ω`,'note')+rect(167,169,49,47,'#fff2d9',3)+line(176,180,206,180,'#be8a56',4)+line(182,197,200,197,'#be8a56',3)+text(145,163,'+','note')+text(147,235,'−','note')+q+arrow(492,94,540,94,'#d5926a',4)+text(440,63,`I = ${n(o.voltage/o.resistance)} A`,'note')+text(470,305,`V = ${o.voltage} V`,'note'),'Rangkaian baterai dan resistor yang tertutup dengan arus konvensional searah');}
});

add('series',{module:8,name:'Rangkaian seri: satu jalur',emoji:'💡',tag:'Listrik',
 observe:'Dua resistor berada di satu jalur. Arus sama melewati keduanya, tetapi tegangan sumber terbagi.',
 question:'Bagaimana hambatan total berubah jika satu resistor tambahan dipasang secara seri?',
 concept:'Untuk rangkaian seri: Rtotal = R₁ + R₂ karena I sama dan Vtotal = V₁ + V₂.',
 derivation:['Di rangkaian seri, I melalui tiap komponen sama.','V = V₁ + V₂ = IR₁ + IR₂ = I(R₁ + R₂).','Bandingkan V = IRtotal sehingga Rtotal = R₁ + R₂.'],
 assumption:'Baterai ideal, resistor ohmik, rangkaian tertutup, tanpa pengaruh suhu. Model menampilkan resistor, bukan klaim tentang tingkat terang lampu nyata.',
 controls:[S('r1','Resistor 1',1,15,1,4,'Ω'),S('r2','Resistor 2',1,15,1,6,'Ω'),S('voltage','Tegangan sumber',3,24,1,12,'V')],
 calc:o=>{const i=o.voltage/(o.r1+o.r2);return explain(`Rtotal = ${o.r1+o.r2} Ω · I = ${n(i)} A`,`V₁ = ${n(i*o.r1)} V, V₂ = ${n(i*o.r2)} V. Keduanya berjumlah ${o.voltage} V.`)},
 render:(o,t)=>{let i=o.voltage/(o.r1+o.r2);return svg(foreground('Satu jalur → arus yang sama')+`<path d="M160 120H600V254H160V120" fill="none" stroke="#679981" stroke-width="6"/>`+rect(278,99,95,44,'#efc98c',7,'#b48f55',3)+rect(418,99,95,44,'#f6d7ab',7,'#b48f55',3)+text(298,126,`R₁ ${o.r1} Ω`,'note')+text(438,126,`R₂ ${o.r2} Ω`,'note')+rect(143,173,35,43,'#f8edcf',3)+text(105,173,'+','note')+text(105,235,'−','note')+arrow(540,113,582,113,'#d38b62',4)+text(335,297,`I = ${n(i)} A di semua resistor`,'note','text-anchor="middle"')+text(400,70,`V = ${o.voltage} V`,'note'),'Rangkaian dua resistor seri dalam satu lintasan tertutup');}
});

add('parallel',{module:8,name:'Rangkaian paralel: cabang arus',emoji:'🔌',tag:'Listrik',
 observe:'Arus membelah menjadi dua cabang, lalu bergabung kembali. Tegangan setiap cabang sama dengan tegangan sumber.',
 question:'Apakah hambatan pengganti dua resistor paralel lebih besar daripada resistor terkecil?',
 concept:'Pada rangkaian paralel, 1/Rtotal = 1/R₁ + 1/R₂; hambatan pengganti dua cabang selalu lebih kecil daripada masing-masing resistor.',
 derivation:['Setiap cabang paralel memiliki tegangan V yang sama.','Arus total = I₁ + I₂ = V/R₁ + V/R₂.','Karena Itotal = V/Rtotal, diperoleh 1/Rtotal = 1/R₁ + 1/R₂. Untuk dua resistor Rtotal = R₁R₂/(R₁+R₂).'],
 assumption:'Sumber tegangan ideal dan resistor ohmik. Diagram menampilkan percabangan arus konvensional.',
 controls:[S('r1','Hambatan cabang atas',2,16,1,6,'Ω'),S('r2','Hambatan cabang bawah',2,16,1,3,'Ω'),S('voltage','Tegangan sumber',3,24,1,12,'V')],
 calc:o=>{const rt=o.r1*o.r2/(o.r1+o.r2);return explain(`Rtotal = ${n(rt)} Ω · Itotal = ${n(o.voltage/rt)} A`,`I₁ = ${n(o.voltage/o.r1)} A; I₂ = ${n(o.voltage/o.r2)} A. Arus total = ${n(o.voltage/o.r1+o.voltage/o.r2)} A.`)},
 render:(o,t)=>{return svg(foreground('Dua cabang → tegangan sama')+`<path d="M150 140H250V97H580V259H250V218H150V140M250 97V218M250 218H580" stroke="#609985" stroke-width="6" fill="none"/>`+rect(355,78,100,40,'#efc48b',5,'#aa8b59',3)+rect(355,197,100,40,'#efc48b',5,'#aa8b59',3)+text(365,104,`R₁ = ${o.r1} Ω`,'note')+text(365,224,`R₂ = ${o.r2} Ω`,'note')+text(80,112,'+','note')+text(80,243,'−','note')+rect(134,166,34,32,'#fff1d4',3)+arrow(295,97,342,97,'#d89062',4)+arrow(295,218,342,218,'#d89062',4)+text(505,59,`I₁ = ${n(o.voltage/o.r1)} A`,'tiny')+text(506,278,`I₂ = ${n(o.voltage/o.r2)} A`,'tiny')+text(80,315,`V cabang = ${o.voltage} V`,'note'),'Rangkaian dua resistor paralel yang membagi arus ke dua jalur');}
});

add('kinetic',{module:11,name:'Energi gerak dan kelajuan',emoji:'⚽',tag:'Energi',
 observe:'Saat kelajuan dibuat dua kali lebih besar, energi kinetiknya empat kali lebih besar karena bergantung pada kuadrat v.',
 question:'Jika kelajuan bola berubah dari 3 ke 6 m/s dengan massa sama, berapa kali energi kinetiknya?',
 concept:'Energi kinetik adalah energi gerak. Eₖ = ½mv² dan terkait usaha yang diperlukan untuk mengubah kelajuan benda.',
 derivation:['Usaha W = Fs. Untuk gaya konstan dengan arah gerak, F=ma.','Dari kinematika v²−v₀² = 2as, sehingga mas = ½m(v²−v₀²).','Usaha total = ΔEₖ; jika mula-mula diam, Eₖ = ½mv².'],
 assumption:'Gerak translasi, massa konstan, tanpa energi rotasi yang signifikan. Animasi kelajuan diperlambat; formula berlaku pada kecepatan nonrelativistik.',
 controls:[S('mass','Massa',.5,5,.5,2,'kg'),S('speed','Kelajuan',1,12,1,3,'m/s')],
 calc:o=>explain(`Eₖ = ${n(.5*o.mass*o.speed**2)} J`,`½ × ${n(o.mass)} × ${o.speed}² = ${n(.5*o.mass*o.speed**2)} J. Pada massa tetap, v dua kali → Eₖ empat kali.`),
 render:(o,t)=>{const x=140+((t*o.speed*9)%440);return svg(foreground('Kelajuan menentukan energi gerak')+line(95,263,692,263,'#abc0ac',8)+circ(x,229,35+o.mass*2,'#f2c37b','#a77f56',3)+`<path d="M${x-19} 221l18-17l20 19l-20 23z" fill="none" stroke="#a77f56" stroke-width="3"/>`+arrow(x+60,230,x+60+o.speed*11,230,'#45977c',5)+text(102,93,`v = ${o.speed} m/s`,'note')+text(102,118,`m = ${n(o.mass)} kg`,'tiny')+text(450,100,`Eₖ = ${n(.5*o.mass*o.speed**2)} J`,'note'),'Bola bergerak mendatar dengan panah kelajuan, energi kinetik bertambah kuadrat kelajuan');}
});

add('potential',{module:11,name:'Ketinggian menyimpan energi',emoji:'🏗️',tag:'Energi',
 observe:'Benda yang terangkat mempunyai energi potensial gravitasi lebih besar relatif terhadap lantai yang dipilih sebagai acuan.',
 question:'Mengapa menaikkan benda setinggi dua kali dengan berat tetap membutuhkan usaha dua kali pada kondisi ideal?',
 concept:'Energi potensial gravitasi dekat permukaan Bumi adalah Eₚ = mgh relatif terhadap acuan. Kenaikan energi diperoleh dari usaha melawan berat.',
 derivation:['Berat benda W = mg.','Usaha untuk mengangkat perlahan setinggi h: usaha = gaya × jarak = mg × h.','Usaha tersebut meningkatkan energi potensial: ΔEₚ = mgh.'],
 assumption:'g = 10 m/s², medan gravitasi dianggap seragam, benda diangkat perlahan dan tanpa kehilangan energi. Titik nol energi ditetapkan di lantai.',
 controls:[S('mass','Massa',1,10,1,3,'kg'),S('height','Tinggi',1,10,1,2,'m')],
 calc:o=>explain(`Eₚ = ${n(o.mass*10*o.height)} J`,`mgh = ${o.mass} × 10 × ${o.height} = ${n(o.mass*10*o.height)} J, dengan lantai sebagai acuan.`),
 render:(o,t)=>{const hpx=o.height*22,y=271-hpx;return svg(foreground('Ketinggian diukur dari garis acuan')+line(90,279,650,279,'#b5c9ac',8)+line(400,271,400,y,'#c09d72',4,'stroke-dasharray="6 5"')+rect(350,y-58,100,58,'#eebd80',6,'#b58956',3)+text(385,y-25,`${o.mass} kg`,'note')+arrow(474,271,474,y,'#4c9a80',4)+text(489,160,`h = ${o.height} m`,'note')+text(99,83,`Eₚ = ${n(o.mass*10*o.height)} J`,'note')+text(116,313,'lantai: Eₚ = 0','tiny'),'Balok terangkat pada suatu ketinggian di atas lantai acuan');}
});

add('efficiency',{module:11,name:'Ke mana perginya energi?',emoji:'☀️',tag:'Perubahan energi',
 observe:'Energi tidak hilang, tetapi tidak semuanya menjadi keluaran yang kita inginkan. Lihat aliran energi masuk, keluaran berguna dan yang tidak menjadi keluaran berguna.',
 question:'Jika 500 J masuk dan 100 J menjadi listrik, berapa efisiensinya dan berapa energi sisanya?',
 concept:'Efisiensi adalah rasio keluaran energi berguna terhadap energi masukan. Energi masukan = energi berguna + energi lainnya (sistem sesuai batas pengukuran).',
 derivation:['Tentukan dulu bagian energi keluaran yang dianggap berguna.','Efisiensi η = Eberguna/Emasuk × 100%.','Energi selain keluaran berguna = Emasuk − Eberguna, sesuai hukum kekekalan energi.'],
 assumption:'Model memakai satu aliran masukan dan dua kategori keluaran; seluruh energi diasumsikan tercatat dan keluaran berguna tidak melebihi energi masuk.',
 controls:[S('input','Energi masuk',200,1500,100,500,'J'),S('eta','Persentase keluaran berguna',10,100,5,20,'%')],
 calc:o=>explain(`Berguna ${n(o.input*o.eta/100)} J · lainnya ${n(o.input*(1-o.eta/100))} J`,`η = ${o.eta}%. Energi berguna = ${o.input} × ${o.eta}/100 = ${n(o.input*o.eta/100)} J.`),
 render:(o,t)=>{const h1=150*o.eta/100,h2=150-h1;return svg(foreground('Energi masuk = jumlah seluruh keluaran')+rect(66,120,160,90,'#f6d594',15)+text(91,155,'Masuk','note')+text(91,183,`${o.input} J`,'note')+arrow(228,165,365,165,'#be916b',6)+rect(387,95,240,45,'#b5e0c2',9)+rect(387,155,240,98,'#f4ccb5',9)+rect(387,95,240*o.eta/100,45,'#67b08d',9)+text(402,123,`Berguna: ${n(o.input*o.eta/100)} J`,'note')+text(402,201,`Lainnya: ${n(o.input*(1-o.eta/100))} J`,'note')+text(402,230,`(${100-o.eta}%)`,'tiny')+text(80,278,`η = ${o.eta}%`,'note'),'Alur energi masukan terbagi ke keluaran berguna dan keluaran lain sesuai konservasi energi');}
});

add('genetics',{module:5,name:'Persilangan sifat: kotak Punnett',emoji:'🧬',tag:'Pewarisan sifat',
 observe:'Setiap induk memberikan satu alel kepada keturunannya. Empat kotak menunjukkan peluang kombinasi gamet, bukan empat anak yang pasti lahir.',
 question:'Persilangan Uu × Uu: berapa peluang keturunan putih jika putih hanya muncul pada uu?',
 concept:'Dalam contoh dominansi lengkap, alel U (ungu) dominan terhadap u (putih). Genotipe uu putih, sedangkan UU dan Uu ungu.',
 derivation:['Tuliskan dua kemungkinan gamet dari masing-masing induk. UU menghasilkan U saja, Uu menghasilkan U atau u, uu menghasilkan u saja.','Gabungkan setiap pasangan gamet dalam kotak Punnett.','Hitung peluang fenotipe, bukan menganggap hasil untuk empat anak harus tepat 3:1.'],
 assumption:'Satu gen dua alel, dominansi lengkap, segregasi gamet Mendel, peluang gamet sama, tanpa pengaruh faktor lain.',
 controls:[C('parent1','Genotipe induk pertama',[['UU','UU'],['Uu','Uu'],['uu','uu']],'Uu'),C('parent2','Genotipe induk kedua',[['UU','UU'],['Uu','Uu'],['uu','uu']],'Uu')],
 calc:o=>{let combinations=[];for(const a of o.parent1)for(const b of o.parent2){const g=[a,b].sort((x,y)=>x==='U'?-1:y==='U'?1:0).join('');combinations.push(g)}const white=combinations.filter(x=>x==='uu').length;return explain(`${n((4-white)*25)}% ungu · ${n(white*25)}% putih`,`Kemungkinan genotipe: ${combinations.join(', ')}. Putih hanya pada uu (${white} dari 4 kombinasi yang sama peluangnya).`)},
 render:(o,t)=>{const p1=o.parent1.split(''),p2=o.parent2.split('');let cells='';for(let i=0;i<2;i++)for(let j=0;j<2;j++){const genes=[p1[i],p2[j]].sort((a,b)=>a==='U'?-1:b==='U'?1:0).join('');const x=268+j*108,y=90+i*90;cells+=rect(x,y,102,83,genes==='uu'?'#fff5ed':'#ead4f2',10,'#bcafca',2)+text(x+51,y+50,genes,'note','text-anchor="middle"')};return svg(foreground('Setiap kotak = satu kemungkinan kombinasi gamet')+cells+text(290,71,p2[0],'note')+text(397,71,p2[1],'note')+text(228,136,p1[0],'note')+text(228,229,p1[1],'note')+text(280,287,`${o.parent1} × ${o.parent2}`,'note')+text(62,330,'U = dominan (ungu); uu = resesif (putih)','tiny'),'Kotak Punnett dua kali dua untuk persilangan dua alel');}
});

add('scientific',{module:1,name:'Eksperimen adil: satu variabel',emoji:'🔬',tag:'Metode ilmiah',
 observe:'Bandingkan tanaman A dan B. Keduanya memperoleh air, jenis tanah, dan suhu yang sama. Hanya jumlah cahaya yang berbeda.',
 question:'Apa yang menjadi variabel bebas, variabel terikat, dan variabel kontrol pada percobaan pengaruh cahaya terhadap pertumbuhan?',
 concept:'Variabel bebas diubah peneliti, variabel terikat diukur sebagai respons, dan variabel kontrol dibuat setara. Ulangan serta pengacakan membantu mengurangi ketidakpastian.',
 derivation:['Rumusan masalah: apakah intensitas cahaya memengaruhi pertumbuhan tanaman?','Variabel bebas: cahaya; variabel terikat: pertumbuhan yang diukur (misalnya tinggi tanaman setelah 14 hari).','Variabel kontrol: air, jenis tanah, bibit, lama pengamatan. Untuk menyimpulkan, lakukan pengukuran dan ulangan, bukan hanya menebak.'],
 assumption:'Gambar tidak menyajikan hasil pengamatan atau mengklaim tanaman tertentu lebih tinggi; tinggi ikon tetap sama sampai data eksperimen sungguhan tersedia.',
 controls:[C('light','Perlakuan tanaman B',[['low','Cahaya lebih sedikit'],['same','Cahaya sama'],['high','Cahaya lebih banyak']],'low'),C('water','Air kedua pot',[['same','Sama banyak'],['different','Berbeda (tidak adil)']],'same')],
 calc:o=>explain(o.water==='same'?'Perbandingan terkendali untuk variabel cahaya':'Percobaan belum adil: air juga berubah',o.light==='same'?'Tanpa perbedaan perlakuan cahaya, kelompok ini tidak menguji pengaruh tingkat cahaya.':'Catat pertumbuhan dari beberapa ulangan; tanpa data, belum bisa menyimpulkan dampak cahaya.'),
 render:(o,t)=>{const plant=(x,sun,water)=>rect(x-42,240,84,45,'#d5a282',5)+line(x,240,x,149,'#5b9869',8)+`<path d="M${x} 199Q${x-56} 167 ${x-68} 190Q${x-48} 229 ${x} 213M${x} 188Q${x+46} 148 ${x+55} 176Q${x+47} 208 ${x} 206" fill="#90c57b"/>`+circ(x+64,89,15,sun?'#f5c96c':'#e3e5dc')+text(x-52,310,`Air: ${water}`,'tiny');return svg(foreground('Perlakuan yang diubah harus jelas')+plant(240,true,'sama')+plant(520,o.light==='high',o.water==='same'?'sama':'beda')+text(202,60,'Tanaman A','note')+text(482,60,'Tanaman B','note')+text(155,332,'ukur tinggi tanaman setelah masa yang sama','tiny'),'Dua pot tanaman untuk pengujian pengaruh cahaya dengan pengendalian air');}
});

add('classification',{module:2,name:'Mengenali ciri makhluk hidup',emoji:'🌿',tag:'Klasifikasi',
 observe:'Pilih kelompok hewan. Lihat ciri yang digunakan untuk menempatkannya, bukan hanya kemiripan satu bagian tubuh.',
 question:'Apakah sayap pada kelelawar dan kupu-kupu berarti keduanya kelompok hewan yang paling dekat?',
 concept:'Klasifikasi berdasarkan banyak karakter dan kekerabatan evolusioner. Kemiripan satu fungsi, seperti terbang, bisa berkembang pada cabang berbeda.',
 derivation:['Mulai dengan ciri dasar: bertulang belakang atau tidak.','Untuk vertebrata, perhatikan ciri turunan seperti rambut dan kelenjar susu (mamalia), bulu sejati (aves), insang (banyak ikan).','Buat kesimpulan dari banyak ciri yang konsisten, bukan hanya dari habitat atau cara berpindah.'],
 assumption:'Diagram klasifikasi sederhana untuk konsep SD, bukan pohon filogenetik lengkap. Contoh hewan dipilih untuk membedakan karakter.',
 controls:[C('animal','Pilih hewan',[['bat','Kelelawar'],['bird','Burung'],['butterfly','Kupu-kupu'],['fish','Ikan']],'bat')],
 calc:o=>{const z={bat:['Vertebrata → Mamalia','Bertulang belakang, rambut, menyusui anak'],bird:['Vertebrata → Aves','Bertulang belakang, bulu sejati'],butterfly:['Invertebrata → Arthropoda/Insecta','Eksoskeleton, tiga pasang kaki'],fish:['Vertebrata → Kelompok ikan','Bertulang belakang, bernapas dengan insang pada sebagian besar spesies']};return explain(z[o.animal][0],z[o.animal][1])},
 render:(o,t)=>{const items=[['bat','Kelelawar',182],['bird','Burung',305],['butterfly','Kupu-kupu',430],['fish','Ikan',558]];return svg(foreground('Cabang ciri, bukan urutan lebih tinggi-rendah')+rect(290,55,180,42,'#deecd8',10)+text(327,82,'Hewan','note')+line(379,97,379,131,'#8eafa2',3)+line(182,131,558,131,'#8eafa2',3)+items.map(([id,label,x])=>line(x,131,x,182,'#8eafa2',3)+rect(x-65,181,130,61,id===o.animal?'#f6d991':'#eef4ed',9,id===o.animal?'#d9b362':'#d8e0d5',2)+text(x,218,label,'tiny','text-anchor="middle"')).join('')+text(160,277,'Amati: tulang belakang, penutup tubuh, cara reproduksi','tiny'),'Bagan sederhana memilih hewan dan membandingkan ciri untuk klasifikasi');}
});

add('circulation',{module:3,name:'Perjalanan darah dan oksigen',emoji:'❤️',tag:'Sistem organ',
 observe:'Darah dari tubuh kembali ke jantung kanan, dipompa ke paru-paru, lalu ke jantung kiri sebelum diedarkan ke tubuh.',
 question:'Pembuluh apa membawa darah kaya oksigen dari paru-paru kembali ke jantung?',
 concept:'Peredaran ganda manusia melewati paru-paru dan jaringan tubuh. Arteri pulmonalis membawa darah rendah O₂; vena pulmonalis membawa darah kaya O₂.',
 derivation:['Jantung kanan → arteri pulmonalis → kapiler paru untuk pertukaran gas.','Paru → vena pulmonalis → jantung kiri.','Jantung kiri → aorta → jaringan tubuh → vena kava → jantung kanan.'],
 assumption:'Bagan alur, bukan anatomi atau perbandingan tekanan detail. Warna merah/biru mengilustrasikan kandungan O₂ relatif, bukan warna asli darah.',
 controls:[C('route','Pilih jalur',[['lung','Dari jantung ke paru-paru'],['body','Dari jantung ke tubuh']],'lung')],
 calc:o=>explain(o.route==='lung'?'Sirkulasi paru-paru':'Sirkulasi sistemik',o.route==='lung'?'Jantung kanan → paru → jantung kiri. Vena pulmonalis mengembalikan darah kaya O₂.':'Jantung kiri → tubuh → jantung kanan. Aorta memasok darah kaya O₂ ke jaringan.'),
 render:(o,t)=>{const active=o.route==='lung';return svg(foreground('Sirkulasi darah melalui dua jalur')+rect(291,118,167,102,'#f6c4bb',24,'#cc958f',2)+text(339,163,'Jantung','note')+text(338,191,'kanan | kiri','tiny')+rect(78,112,150,120,'#d8edf7',42,'#9dbcc9',3)+text(132,173,'Paru','note')+rect(529,112,150,120,'#e1eddd',30,'#a5c7a2',3)+text(567,174,'Tubuh','note')+arrow(290,141,228,141,active?'#537aaf':'#c5d0c9',6)+arrow(228,199,290,199,active?'#d48182':'#c5d0c9',6)+arrow(457,141,528,141,!active?'#d48182':'#c5d0c9',6)+arrow(528,199,457,199,!active?'#537aaf':'#c5d0c9',6)+text(85,78,'pertukaran O₂/CO₂','tiny')+text(515,78,'distribusi O₂','tiny')+text(152,281,'Biru: relatif rendah O₂ · Merah: relatif kaya O₂','tiny'),'Skema aliran darah antara paru-paru, jantung, dan tubuh');}
});

add('reflex',{module:3,name:'Refleks menarik tangan',emoji:'✋',tag:'Sistem saraf',
 observe:'Reseptor kulit mendeteksi panas, sinyal masuk ke sumsum tulang belakang, lalu perintah keluar lewat saraf motorik ke otot.',
 question:'Mengapa tangan bisa menarik diri sebelum kita sadar penuh bahwa benda itu panas?',
 concept:'Respons refleks tertentu menggunakan rangkaian neuron di sumsum tulang belakang. Informasi juga diteruskan ke otak untuk kesadaran rasa sakit.',
 derivation:['Rangsang panas ditangkap reseptor sensorik.','Neuron sensorik membawa impuls menuju sumsum tulang belakang.','Interneuron dan neuron motorik mengaktifkan otot untuk menarik tangan; otak kemudian memproses sensasi sadar.'],
 assumption:'Alur disederhanakan; tidak semua gerak dan refleks memiliki jalur identik. Contoh ini menggambarkan refleks penarikan.',
 controls:[C('phase','Amati tahap',[['0','1. Sentuh panas'],['1','2. Sinyal sensorik'],['2','3. Sumsum tulang belakang'],['3','4. Otot menarik tangan']],'0')],
 calc:o=>explain(['Reseptor kulit','Neuron sensorik','Sumsum tulang belakang','Neuron motorik dan otot'][+o.phase],['Rangsang panas dideteksi reseptor.','Impuls saraf bergerak ke sumsum tulang belakang.','Rangkaian saraf membentuk respons cepat.','Otot berkontraksi dan tangan menjauh.'][+o.phase]),
 render:(o,t)=>{const labels=['Kulit','Saraf sensorik','Sumsum belakang','Saraf motorik & otot'],xx=[89,240,397,555];return svg(foreground('Lintasan respons refleks sederhana')+labels.map((label,i)=>rect(xx[i],122,145,87,i===+o.phase?'#f6d99e':'#dfebde',14,i===+o.phase?'#d3ab60':'#a5c5ae',2)+text(xx[i]+72,162,label.split(' & ')[0],'tiny','text-anchor="middle"')+(label.includes('&')?text(xx[i]+72,184,'& otot','tiny','text-anchor="middle"'):'')+(i<3?arrow(xx[i]+145,167,xx[i+1]-5,167,'#93b29e',3):'')).join('')+text(93,277,'Impuls cepat diproses; persepsi sadar melibatkan otak.','note'),'Bagan empat tahap refleks penarikan tangan');}
});

add('photosynthesis',{module:4,name:'Apa yang membatasi fotosintesis?',emoji:'🍃',tag:'Tumbuhan',
 observe:'Cahaya, karbon dioksida, dan air dibutuhkan untuk fotosintesis. Kekurangan salah satu faktor dapat membatasi proses.',
 question:'Jika cahaya sangat cukup tetapi CO₂ sangat rendah, apakah menambah cahaya terus pasti menaikkan fotosintesis?',
 concept:'Dalam kisaran tertentu, laju fotosintesis dibatasi faktor yang paling tidak mencukupi. Proses keseluruhannya mengubah CO₂ dan air menjadi karbohidrat dan oksigen dengan bantuan energi cahaya.',
 derivation:['Daun menangkap energi cahaya melalui pigmen fotosintetik.','CO₂ menyediakan karbon; air menjadi sumber elektron pada reaksi terang dan ikut menghasilkan O₂.','Kekurangan satu faktor dapat membatasi laju meskipun faktor lain berlimpah.'],
 assumption:'Indikator keterbatasan merupakan ilustrasi kualitatif, bukan model numerik laju fotosintesis sesungguhnya. Hubungan nyata tidak linier sederhana dan dipengaruhi suhu serta banyak faktor lain.',
 controls:[S('light','Ketersediaan cahaya',10,100,10,90,'%'),S('co2','Ketersediaan CO₂',10,100,10,30,'%'),S('water','Ketersediaan air',10,100,10,80,'%')],
 calc:o=>{const min=Math.min(o.light,o.co2,o.water);const names=Object.entries({light:'cahaya',co2:'CO₂',water:'air'}).filter(([k,v])=>o[k]===min).map(x=>x[1]);return explain(`Faktor paling terbatas: ${names.join(' & ')}`,`Cahaya ${o.light}%, CO₂ ${o.co2}%, air ${o.water}%. Persentase di sini pengatur ilustratif, bukan prediksi jumlah glukosa atau O₂.`)},
 render:(o,t)=>{return svg(foreground('Satu faktor kekurangan dapat membatasi proses')+`<path d="M360 254Q291 190 361 102Q452 157 360 254" fill="#8cca89" stroke="#669d70" stroke-width="4"/>`+line(362,248,365,116,'#4b905c',4)+circ(131,110,34,'#f7d16f')+arrow(165,120,304,166,'#deac58',5)+arrow(610,102,440,164,'#74a4b7',5)+arrow(131,259,292,224,'#62a6c2',5)+text(87,62,`Cahaya ${o.light}%`,'note')+text(520,62,`CO₂ ${o.co2}%`,'note')+text(66,299,`Air ${o.water}%`,'note')+text(480,269,'O₂ + hasil fotosintesis','tiny'),'Daun dengan tiga masukan fotosintesis, cahaya karbon dioksida air');}
});

add('tropism',{module:4,name:'Batang tumbuh menuju cahaya',emoji:'🌱',tag:'Tumbuhan',
 observe:'Perhatikan arah pertumbuhan batang yang lebih lama terpapar cahaya satu sisi. Respons ini terjadi melalui pertumbuhan, bukan batang berputar seketika.',
 question:'Apakah batang yang melengkung ke arah jendela termasuk fototropisme positif atau negatif?',
 concept:'Fototropisme positif ialah pertumbuhan ke arah cahaya. Pada banyak tunas, distribusi auksin yang tidak merata mendorong pemanjangan sel berbeda di kedua sisi.',
 derivation:['Cahaya datang lebih banyak dari satu arah.','Distribusi sinyal pertumbuhan membuat sisi batang memanjang tidak sama.','Perbedaan pertumbuhan kumulatif membuat batang melengkung ke arah sumber cahaya.'],
 assumption:'Diagram memperlihatkan hasil pertumbuhan selama waktu lama, bukan perubahan langsung. Respons sesungguhnya bergantung spesies, usia dan intensitas cahaya.',
 controls:[C('light','Arah cahaya',[['left','Dari kiri'],['right','Dari kanan'],['top','Dari atas']],'right')],
 calc:o=>explain(o.light==='top'?'Tunas tumbuh relatif tegak':`Tunas membengkok ke ${o.light==='left'?'kiri':'kanan'}`,'Pada fototropisme positif, arah pertumbuhan dipengaruhi arah datangnya cahaya.'),
 render:(o,t)=>{let bend=o.light==='left'?-100:o.light==='right'?100:0,base=355;return svg(foreground('Arah pertumbuhan dalam beberapa hari')+rect(285,268,142,50,'#cb9874',11)+`<path d="M${base} 266Q${base-15} 195 ${base+bend} 118" stroke="#6ba47a" stroke-width="16" fill="none" stroke-linecap="round"/>`+`<path d="M${base+(.3*bend)} 208Q${base-80+(.3*bend)} 163 ${base-90+(.3*bend)} 192Q${base-70} 234 ${base+(.3*bend)} 219" fill="#89bf82"/>`+circ(o.light==='left'?108:o.light==='right'?637:355,o.light==='top'?67:115,34,'#f7d278')+text(77,67,'cahaya','note')+arrow(o.light==='left'?149:o.light==='right'?590:360,o.light==='top'?88:123,o.light==='left'?260:o.light==='right'?480:360,155,'#e6b35d',4)+text(428,305,'pertumbuhan ≠ gerakan seketika','tiny'),'Batang tanaman melengkung ke arah cahaya sebagai respons fototropisme positif');}
});

add('cell',{module:5,name:'Bagian sel dan tugasnya',emoji:'🔬',tag:'Biologi sel',
 observe:'Pilih organel. Lokasinya ditandai pada sel tumbuhan sederhana; setiap bagian memiliki fungsi khusus.',
 question:'Organel apa yang berperan dalam fotosintesis? Apa yang menghasilkan banyak ATP dari respirasi aerob?',
 concept:'Kloroplas menangkap energi cahaya untuk fotosintesis; mitokondria menghasilkan banyak ATP lewat respirasi sel aerob; inti mengandung materi genetik pada sel eukariotik.',
 derivation:['Sel terdiri atas bagian dengan fungsi yang berbeda.','Pilih organel berdasarkan proses yang disebut dalam soal, bukan hanya apakah organel terlihat besar.','Bedakan fungsi fotosintesis (kloroplas) dengan respirasi aerob (mitokondria).'],
 assumption:'Sketsa sel tumbuhan, organel tidak dibuat sesuai skala dan jumlah sebenarnya. Sel bakteri tidak memiliki inti sel bermembran.',
 controls:[C('organel','Tandai organel',[['nucleus','Inti sel'],['chloroplast','Kloroplas'],['mitochondria','Mitokondria'],['vacuole','Vakuola']],'chloroplast')],
 calc:o=>explain(({nucleus:'Inti: tempat DNA eukariotik',chloroplast:'Kloroplas: fotosintesis',mitochondria:'Mitokondria: respirasi aerob',vacuole:'Vakuola: penyimpanan dan turgor'})[o.organel],'Hubungkan struktur organel dengan proses yang terjadi di dalamnya.'),
 render:(o,t)=>{let organs='';organs+=circ(305,144,47,'#dbbce3',o.organel==='nucleus'?'#bd5883':'#9b81aa',o.organel==='nucleus'?6:2);organs+=`<ellipse cx="195" cy="199" rx="39" ry="22" fill="#a1cea2" stroke="${o.organel==='chloroplast'?'#d88751':'#79b783'}" stroke-width="${o.organel==='chloroplast'?7:2}"/>`;organs+=`<ellipse cx="437" cy="207" rx="38" ry="21" fill="#f3c3ad" stroke="${o.organel==='mitochondria'?'#cc7052':'#d5a08a'}" stroke-width="${o.organel==='mitochondria'?7:2}"/>`;organs+=`<ellipse cx="365" cy="239" rx="75" ry="38" fill="#cae9e8" stroke="${o.organel==='vacuole'?'#cb8da5':'#95c5ca'}" stroke-width="${o.organel==='vacuole'?7:2}"/>`;return svg(foreground('Sel tumbuhan · gambar skematis')+rect(93,55,575,252,'#a5ce94',48,'#5f9869',7)+rect(108,68,545,226,'#e8f6d7',43,'#b0d2ac',4)+organs+text(510,94,'dinding sel','tiny')+text(120,318,'Pilihan: '+({nucleus:'inti sel',chloroplast:'kloroplas',mitochondria:'mitokondria',vacuole:'vakuola'})[o.organel],'note'),'Skema sel tumbuhan dengan organel inti, kloroplas, mitokondria dan vakuola');}
});

add('orbit',{module:12,name:'Mengapa ada musim?',emoji:'🌍',tag:'Bumi dan antariksa',
 observe:'Sumbu Bumi miring sekitar 23,4° terhadap arah tegak lurus bidang orbit. Ketika belahan utara condong ke Matahari, siang lebih panjang dan sinar lebih langsung di utara.',
 question:'Apakah musim terutama disebabkan perubahan jarak Bumi ke Matahari?',
 concept:'Musim terutama disebabkan kemiringan sumbu rotasi Bumi yang orientasinya kurang lebih tetap ketika Bumi berevolusi, bukan jarak ke Matahari.',
 derivation:['Bumi berevolusi mengelilingi Matahari sambil sumbu rotasinya tetap miring.','Pada sekitar Juni, belahan utara lebih condong ke Matahari. Sekitar Desember, belahan selatan lebih condong.','Kemiringan mengubah sudut datang sinar dan durasi siang sepanjang tahun.'],
 assumption:'Gambar tidak berskala dan menyoroti geometri solstis kira-kira; musim wilayah tropis berbeda pola dari empat musim lintang menengah.',
 controls:[C('season','Posisi tahunan',[['june','Sekitar solstis Juni'],['dec','Sekitar solstis Desember']],'june')],
 calc:o=>explain(o.season==='june'?'Belahan utara condong ke Matahari':'Belahan selatan condong ke Matahari',o.season==='june'?'Sekitar Juni: musim panas astronomis di utara dan musim dingin di selatan.':'Sekitar Desember: musim panas astronomis di selatan dan musim dingin di utara.'),
 render:(o,t)=>{const june=o.season==='june',tilt=june?-23.4:23.4;return svg(foreground('Orientasi sumbu mengubah penyinaran')+circ(132,175,75,'#f8d377')+Array.from({length:5},(_,i)=>arrow(213,116+i*28,390,116+i*28,'#edbd62',3)).join('')+circ(520,176,105,'#a5cbd7','#7eaab8',3)+`<g transform="translate(520 176) rotate(${tilt})">`+line(0,-125,0,125,'#3a8272',5)+`<path d="M-102 0A102 102 0 0 0 102 0" fill="none" stroke="#7ab68d" stroke-width="6"/>`+`<path d="M-99 -16A102 102 0 0 1 99 -16" fill="none" stroke="#f0f1d8" stroke-width="5"/>`+text(12,-91,'U','note')+text(10,110,'S','note')+'</g>'+text(71,284,'Matahari','note')+text(458,314,june?'Juni: utara lebih disinari':'Desember: selatan lebih disinari','tiny'),'Bumi bersumbu miring terhadap pancaran sinar Matahari pada solstis');}
});

add('foodchain',{module:13,name:'Energi pada rantai makanan',emoji:'🐸',tag:'Ekologi',
 observe:'Panah pada rantai makanan menunjukkan arah perpindahan energi dari organisme yang dimakan ke pemakannya.',
 question:'Pada rumput → belalang → katak → ular, siapakah konsumen tingkat II?',
 concept:'Produsen mengubah energi cahaya menjadi energi kimia. Konsumen I memakan produsen, konsumen II memakan konsumen I, dan seterusnya.',
 derivation:['Tentukan produsen pada pangkal rantai makanan.','Hitung tingkat konsumen berdasarkan sumber makanan: belalang I, katak II, ular III.','Energi tersedia umumnya menurun di setiap tingkat trofik karena digunakan dalam proses kehidupan dan terlepas sebagai panas.'],
 assumption:'Contoh memakai ilustrasi aturan kasar 10% perpindahan energi antar tingkat; angka 10% bukan nilai universal ekosistem. Rantai makanan nyata membentuk jejaring.',
 controls:[C('level','Tingkat yang diamati',[['0','Rumput (produsen)'],['1','Belalang (konsumen I)'],['2','Katak (konsumen II)'],['3','Ular (konsumen III)']],'2')],
 calc:o=>{const name=['Rumput · produsen','Belalang · konsumen I','Katak · konsumen II','Ular · konsumen III'][+o.level];return explain(name,'Arah panah selalu dari sumber energi/makanan ke organisme yang menerima energinya.')},
 render:(o,t)=>{const labs=['Rumput','Belalang','Katak','Ular'],em=['🌱','🦗','🐸','🐍'];return svg(foreground('Panah = arah energi menuju pemakan')+labs.map((z,i)=>{const x=38+i*184;return rect(x,121,150,120,i===+o.level?'#f7deaa':'#e9f2e6',17,i===+o.level?'#d6b56c':'#c9dec9',2)+text(x+75,172,em[i],'note','text-anchor="middle"')+text(x+75,207,z,'note','text-anchor="middle"')+(i<3?arrow(x+152,182,x+181,182,'#8da981',3):'')}).join('')+text(74,74,'energi berpindah →','note')+text(78,294,'Energi ke tingkat berikutnya umumnya lebih sedikit.','tiny'),'Rantai makanan rumput belalang katak ular dengan panah aliran energi');}
});

add('immune',{module:14,name:'Mengapa vaksin membantu?',emoji:'🛡️',tag:'Kesehatan',
 observe:'Vaksin mengajarkan sistem kekebalan mengenali antigen tertentu tanpa harus mengalami penyakit akibat infeksi yang sama.',
 question:'Bagaimana memori kekebalan membantu saat tubuh bertemu patogen yang sesuai di kemudian hari?',
 concept:'Vaksinasi dapat membentuk sel memori imun dan antibodi. Respons berikutnya dapat lebih cepat dan lebih efektif, sehingga menurunkan risiko penyakit berat.',
 derivation:['Antigen dari vaksin dikenali sel-sel sistem imun.','Sebagian sel imun berkembang membentuk respons dan memori spesifik.','Saat paparan berikutnya, memori imun membantu respons yang lebih cepat terhadap antigen yang sesuai.'],
 assumption:'Ini bagan konseptual, bukan jadwal dosis, tingkat efektivitas, atau kepastian perlindungan 100%. Efektivitas dan durasi respons bergantung jenis vaksin dan individu.',
 controls:[C('stage','Tahap respons',[['0','1. Sebelum vaksin'],['1','2. Setelah vaksinasi'],['2','3. Paparan berikutnya']],'1')],
 calc:o=>explain(['Belum ada memori spesifik akibat vaksin','Memori imun terbentuk','Memori membantu respons lebih cepat'][+o.stage],'Vaksin tidak bekerja dengan menggantikan sistem imun, melainkan melatih respons imun adaptif pada target tertentu.'),
 render:(o,t)=>{const stage=+o.stage;return svg(foreground('Memori imun membantu saat terpapar lagi')+circ(177,167,66,'#cde8dc','#8fb7a2',3)+circ(395,167,66,stage>=1?'#b5e1c2':'#e8e4d8','#8fb7a2',3)+circ(610,167,66,stage>=2?'#c6e7ca':'#e8e4d8','#8fb7a2',3)+text(128,171,'Pengenalan','tiny')+text(350,170,'Sel memori','tiny')+text(561,170,'Respons','tiny')+arrow(246,167,320,167,'#8ab59d',3)+arrow(465,167,537,167,'#8ab59d',3)+text(108,267,'1. antigen','tiny')+text(358,267,'2. memori','tiny')+text(548,267,'3. paparan lagi','tiny'),'Tahapan pengenalan antigen, pembentukan sel memori, dan respons imun saat paparan berikutnya');}
});

add('magnet',{module:8,name:'Kawat berarus membuat medan magnet',emoji:'🧲',tag:'Magnet',
 observe:'Arus listrik dalam lilitan kawat dapat membentuk elektromagnet. Membalik arah arus membalik orientasi kutub elektromagnet.',
 question:'Mengapa paku besi yang dililit kawat dapat menarik klip ketika kawat dialiri arus?',
 concept:'Muatan listrik bergerak menghasilkan medan magnet. Solenoida berarus menjadi elektromagnet; inti feromagnetik dapat memperkuatnya.',
 derivation:['Arus mengalir pada tiap lilitan penghantar.','Medan magnet lilitan saling memperkuat dalam kumparan.','Inti besi dapat termagnetisasi dan memperkuat elektromagnet selama arus mengalir.'],
 assumption:'Diagram medan magnet kualitatif tanpa menghitung kuat medan. Pembalikan kutub bergantung arah lilitan dan arah arus.',
 controls:[C('power','Sakelar',[['on','Tertutup (arus mengalir)'],['off','Terbuka (tidak mengalir)']],'on'),C('direction','Arah arus',[['forward','Arah pertama'],['reverse','Dibalik']],'forward')],
 calc:o=>explain(o.power==='on'?'Elektromagnet aktif':'Elektromagnet tidak mendapat arus',o.power==='on'?'Garis medan muncul di sekitar lilitan; membalik arus menukar kutub N dan S.':'Tidak ada medan magnet dari arus kumparan; inti mungkin menyimpan kemagnetan sisa.'),
 render:(o,t)=>{const on=o.power==='on';const coils=Array.from({length:8},(_,i)=>`<ellipse cx="${256+i*30}" cy="175" rx="21" ry="58" fill="none" stroke="#cf9b61" stroke-width="5"/>`).join('');return svg(foreground('Kumparan berarus dan inti besi')+rect(232,151,270,48,'#aebbb7',8,'#809c94',2)+coils+(on?`<path d="M242 118Q360 28 500 118M242 232Q360 311 500 232" stroke="#639f8d" stroke-width="4" fill="none" stroke-dasharray="8 7"/>`:'')+text(160,176,on?(o.direction==='forward'?'S':'N'):'—','note')+text(540,176,on?(o.direction==='forward'?'N':'S'):'—','note')+text(110,293,on?'Medan magnet di sekitar kumparan':'Tanpa arus, medan kumparan menghilang','note'),'Kumparan kawat pada inti besi, garis medan magnet saat dialiri arus');}
});

add('fermentation',{module:14,name:'Ragi dan gelembung gas',emoji:'🍞',tag:'Bioteknologi',
 observe:'Ragi memanfaatkan gula untuk metabolisme. Pada fermentasi adonan roti, CO₂ yang dihasilkan dapat terperangkap sehingga adonan mengembang.',
 question:'Gas apakah yang paling langsung menyebabkan adonan roti mengembang?',
 concept:'Dalam fermentasi alkohol oleh ragi, gula diolah menjadi etanol dan CO₂. CO₂ yang terperangkap dalam jaringan gluten ikut membesarkan volume adonan.',
 derivation:['Gula menjadi substrat metabolisme ragi.','Pada kondisi fermentasi alkohol, terbentuk etanol dan CO₂.','Gelembung CO₂ tertahan dalam adonan, sehingga volumenya dapat meningkat.'],
 assumption:'Ilustrasi kualitatif; suhu, jumlah ragi, kadar gula, waktu, dan struktur gluten memengaruhi hasil nyata. Gambar bukan prakiraan volume adonan.',
 controls:[C('sugar','Ketersediaan gula',[['yes','Ada gula yang dapat dimanfaatkan'],['no','Tidak ditambahkan gula']],'yes')],
 calc:o=>explain(o.sugar==='yes'?'Ragi dapat menghasilkan CO₂ dari gula':'Sumber gula langsung lebih terbatas',o.sugar==='no'?'Tepung dapat menyediakan karbohidrat yang diuraikan menjadi gula; jadi tanpa gula tambahan tidak selalu berarti ragi tidak bekerja.':'Gas yang menumpuk dapat memperbesar pori-pori adonan.'),
 render:(o,t)=>{const b=o.sugar==='yes'?12:5;return svg(foreground('Ragi memfermentasi gula → gas CO₂')+`<path d="M188 267Q170 140 255 122Q370 58 482 128Q558 173 538 267Z" fill="#eac999" stroke="#b18e5e" stroke-width="5"/>`+Array.from({length:b},(_,i)=>circ(241+(i*47)%270,142+((i*71+t*3)%106),7+i%3*3,'#fff2d9','#b9a57c',2)).join('')+text(105,76,'gula + ragi','note')+arrow(222,87,275,116,'#d8aa73',4)+text(532,92,'gelembung CO₂','note')+arrow(584,108,470,145,'#d8aa73',4)+text(286,309,'Skema adonan mengembang','tiny'),'Adonan roti dengan gelembung karbon dioksida dari fermentasi ragi');}
});

add('lens',{module:9,name:'Lensa cembung dan bayangan',emoji:'🔍',tag:'Optik',
 observe:'Geser benda mendekati lensa cembung. Jika jarak benda lebih kecil daripada fokus, bayangan maya, tegak, dan diperbesar; jika lebih jauh dari fokus, bayangan nyata dan terbalik.',
 question:'Mengapa kaca pembesar menghasilkan bayangan tegak ketika objek berada di dalam jarak fokus?',
 concept:'Sinar utama pada lensa tipis cembung: sinar sejajar sumbu dibiaskan menuju fokus jauh, sinar melalui pusat optik diteruskan kira-kira lurus. Perpotongan sinar atau perpanjangannya menentukan bayangan.',
 derivation:['Persamaan lensa tipis ideal: 1/f = 1/u + 1/v.','Jarak bayangan v = fu/(u−f); jika u < f maka v negatif dan bayangan bersifat maya.','Perbesaran m = −v/u. Tanda negatif menunjukkan bayangan terbalik (untuk benda di luar fokus).'],
 assumption:'Lensa tipis ideal dan aproksimasi sinar paraaksial. Garis putus-putus adalah perpanjangan balik sinar divergen untuk bayangan maya.',
 controls:[S('object','Jarak benda',40,200,10,100,'satuan gambar'),S('focus','Panjang fokus',40,100,10,70,'satuan gambar')],
 calc:o=>{const u=o.object,f=o.focus,den=u-f;if(den===0)return explain('Benda tepat di fokus: sinar keluar sejajar','Bayangan terbentuk di tak hingga dalam model lensa ideal.');const vv=f*u/den;return explain(vv<0?'Bayangan maya, tegak': 'Bayangan nyata, terbalik',`Jarak bayangan v = ${n(vv)} satuan gambar; perbesaran m = ${n(-vv/u)}.`)},
 render:(o,t)=>{const f=o.focus,u=o.object,lx=392,cy=174,tipY=103,objX=lx-u,den=u-f,imx=den===0?Infinity:lx+f*u/den,m=den===0?Infinity:-f/den,imgY=cy+(tipY-cy)*m;const endX=690,slope1=(cy-tipY)/f,slope2=(cy-tipY)/(lx-objX);const e1Y=tipY+(endX-lx)*slope1,e2Y=cy+(endX-lx)*slope2;let rays=line(objX,tipY,lx,tipY,'#e09a62',3)+line(objX,tipY,lx,cy,'#4c9ca9',3)+line(lx,tipY,endX,e1Y,'#e09a62',3)+line(lx,cy,endX,e2Y,'#4c9ca9',3);if(u<f&&Number.isFinite(imx)){rays+=line(imx,imgY,lx,tipY,'#e09a62',2,'stroke-dasharray="5 6"')+line(imx,imgY,lx,cy,'#4c9ca9',2,'stroke-dasharray="5 6"')}if(Number.isFinite(imx)&&imx>30&&imx<725&&Math.abs(imgY)<450){rays+=arrow(imx,cy,imx,imgY,'#c783ba',4)+text(imx+7,Math.max(32,Math.min(320,imgY-9)),'bayangan','tiny')};return svg(foreground('Sinar istimewa lensa tipis cembung')+line(60,cy,705,cy,'#afb8af',2,'stroke-dasharray="7 5"')+`<path d="M392 63Q360 174 392 292Q424 174 392 63Z" fill="#a9dbe1" stroke="#539ca5" stroke-width="4"/>`+circ(lx-f,cy,5,'#d48b56')+circ(lx+f,cy,5,'#d48b56')+text(lx-f,cy+22,'F','tiny','text-anchor="middle"')+text(lx+f,cy+22,'F','tiny','text-anchor="middle"')+rays+arrow(objX,cy,objX,tipY,'#5ca278',5)+text(objX-28,93,'benda','tiny')+text(556,321,u<f?'maya · tegak':'nyata · terbalik','note'),'Diagram sinar pada lensa cembung untuk posisi objek relatif terhadap fokus');}
});


add('convexmirror',{module:9,name:'Cermin cembung memperluas pandangan',emoji:'🪞',tag:'Optik',
 observe:'Sinar pantul menyebar. Perpanjangannya seolah-olah bertemu di belakang cermin, sehingga bayangan tampak lebih kecil dan tegak.',
 question:'Mengapa cermin cembung dipakai di tikungan, padahal bayangannya lebih kecil?',
 concept:'Cermin cembung menyebarkan sinar pantul sehingga memberi bidang pandang lebih luas. Untuk benda nyata, bayangan yang terbentuk maya, tegak, dan diperkecil.',
 derivation:['Bentuk permukaan cermin melengkung ke arah benda.','Sinar datang dari benda dipantulkan menyebar.','Perpanjangan sinar pantul di belakang cermin bersilangan membentuk lokasi bayangan maya.'],
 assumption:'Sketsa sinar ideal, tidak menggunakan skala panjang fokus. Semua cermin tetap mengikuti hukum sudut datang sama dengan sudut pantul terhadap normal setempat.',
 controls:[C('view','Pengamatan',[['wide','Cermin cembung'],['flat','Cermin datar sebagai pembanding']],'wide')],
 calc:o=>explain(o.view==='wide'?'Bidang pandang lebih luas · bayangan diperkecil':'Cermin datar · ukuran bayangan sama','Cermin cembung memungkinkan melihat lebih banyak area, tetapi objek tampak lebih kecil.'),
 render:(o,t)=>svg(foreground('Cermin lengkung memantulkan sinar menyebar')+`<path d="M490 62Q${o.view==='wide'?450:490} 172 490 290" stroke="#609fa6" stroke-width="13" fill="none"/>`+arrow(130,86,475,123,'#d58e68',4)+arrow(134,240,475,230,'#d58e68',4)+arrow(475,123,185,o.view==='wide'?55:155,'#5d9bac',4)+arrow(475,230,185,o.view==='wide'?294:196,'#5d9bac',4)+text(88,56,'sinar dari objek','note')+text(493,74,'cermin','tiny')+text(90,315,o.view==='wide'?'sinar pantul menyebar lebih lebar':'bandingkan sebaran sinar','note'),'Sinar pantul menyebar pada cermin cembung')
});

add('eclipse',{module:12,name:'Susunan benda saat gerhana',emoji:'🌘',tag:'Antariksa',
 observe:'Gerhana Matahari terjadi saat Bulan berada di antara Matahari dan Bumi. Gerhana Bulan terjadi saat Bumi berada di antara Matahari dan Bulan.',
 question:'Manakah urutan benda dari Matahari untuk gerhana Matahari dan gerhana Bulan?',
 concept:'Gerhana memerlukan keselarasan posisi Matahari, Bumi, Bulan yang cukup tepat dan ketiganya tidak selalu segaris karena bidang orbit Bulan miring.',
 derivation:['Gerhana Matahari: cahaya Matahari terhalang Bulan, bayangannya jatuh ke bagian Bumi.','Gerhana Bulan: Bumi menghalangi cahaya Matahari ke Bulan.','Gerhana tidak terjadi tiap bulan baru/purnama karena orbit Bulan miring sekitar 5° terhadap bidang ekliptika.'],
 assumption:'Skema tidak berskala. Ukuran dan jarak benda digambar untuk memperlihatkan urutan, bukan proporsi astronomis.',
 controls:[C('type','Jenis gerhana',[['solar','Gerhana Matahari'],['lunar','Gerhana Bulan']],'solar')],
 calc:o=>explain(o.type==='solar'?'Matahari → Bulan → Bumi':'Matahari → Bumi → Bulan',o.type==='solar'?'Bayangan Bulan dapat jatuh ke sebagian permukaan Bumi.':'Bayangan Bumi jatuh pada Bulan dan Bulan dapat tampak meredup atau kemerahan.'),
 render:(o,t)=>{const solar=o.type==='solar';return svg(foreground('Perhatikan benda yang berada di tengah')+circ(144,166,73,'#f4c963')+circ(solar?386:597,166,solar?30:26,'#c9d0d5','#98abb5',3)+circ(solar?597:386,166,solar?55:55,'#8ebbd8','#6ba4c4',3)+`<path d="M${solar?410:435} ${solar?147:120}L680 106L680 232L${solar?410:435} ${solar?186:212}Z" fill="#b1bcc3" opacity=".35"/>`+text(94,277,'Matahari','note')+text(331,277,solar?'Bulan':'Bumi','note')+text(567,277,solar?'Bumi':'Bulan','note'),'Keselarasan benda langit pada gerhana Matahari atau gerhana Bulan');}
});

add('seismograph',{module:12,name:'Gelombang gempa pada seismograf',emoji:'🌋',tag:'Kebumian',
 observe:'Seismograf merekam gerakan tanah sebagai jejak sinyal terhadap waktu. Amplitudo getaran dapat bertambah selama gelombang gempa melintas.',
 question:'Apakah seismograf digunakan untuk mengukur tekanan udara atau gerakan tanah?',
 concept:'Seismograf mencatat getaran tanah, sedangkan rekamannya disebut seismogram. Alat ini berbeda dari barometer, higrometer, dan anemometer.',
 derivation:['Gempa melepaskan energi mekanik yang merambat melalui Bumi sebagai gelombang seismik.','Sensor menangkap pergerakan tanah relatif terhadap sistem acuan instrumen.','Sinyal amplitudo terhadap waktu membantu analisis gelombang seismik; amplitudo saja bukan ukuran magnitudo langsung.'],
 assumption:'Sinyal pada gambar sintetik untuk ilustrasi, bukan data gempa nyata atau rumus memperkirakan magnitudo.',
 controls:[S('amplitude','Besar getaran ilustratif',5,55,5,25,'px'),C('quake','Keadaan',[['off','Sebelum gempa'],['on','Gelombang terekam']],'on')],
 calc:o=>explain(o.quake==='on'?'Seismogram menampilkan gelombang':'Tanah tenang: jejak mendekati garis datar','Besar amplitudo dapat berubah ketika gelombang berbeda melintas; alatnya mencatat respons tanah.'),
 render:(o,t)=>{let pts=[];for(let x=75;x<690;x+=4){let signal=o.quake==='on'?o.amplitude*Math.sin((x-75)*.1+t*1.5)*Math.exp(-Math.pow((x-380)/190,2)):0;pts.push(`${x},${170+signal}`)}return svg(foreground('Grafik: simpangan terhadap waktu')+grid(75,65,610,220)+line(75,170,690,170,'#9aada0',2)+`<polyline points="${pts.join(' ')}" fill="none" stroke="#c78765" stroke-width="4"/>`+text(307,318,'waktu →','note')+text(92,62,'simpangan','tiny'),'Seismogram sintetis sebagai hasil pembacaan getaran tanah');}
});

add('digestion',{module:3,name:'Makanan menempuh sistem pencernaan',emoji:'🍎',tag:'Fisiologi',
 observe:'Makanan melewati mulut, kerongkongan, lambung, usus halus, kemudian usus besar. Proses enzimatik berbeda di tiap tahap.',
 question:'Enzim amilase dalam air liur mulai memecah kelompok zat makanan apa?',
 concept:'Amilase memecah pati/amilum menjadi molekul karbohidrat yang lebih kecil. Protein terutama diuraikan protease; lemak dibantu lipase.',
 derivation:['Di mulut, gigi memecah makanan secara mekanik dan amilase mulai mencerna pati.','Di lambung, lingkungan asam serta pepsin berperan dalam pencernaan protein.','Di usus halus, banyak pencernaan lanjutan dan penyerapan zat gizi berlangsung.'],
 assumption:'Bagan menunjukkan urutan organ, bukan panjang atau seluruh enzim yang terlibat. Pencernaan tidak selesai seluruhnya hanya dalam satu organ.',
 controls:[C('stage','Pilih lokasi',[['0','Mulut'],['1','Lambung'],['2','Usus halus'],['3','Usus besar']],'0')],
 calc:o=>explain(['Mulut: mengunyah dan amilase','Lambung: protein mulai dicerna','Usus halus: pencernaan dan penyerapan','Usus besar: penyerapan air dan pembentukan feses'][+o.stage],'Amilase saliva terutama bekerja terhadap amilum, bukan protein atau lemak.'),
 render:(o,t)=>{const labels=['Mulut','Lambung','Usus halus','Usus besar'];return svg(foreground('Tahap kerja organ pencernaan')+labels.map((z,i)=>{let x=35+i*185;return rect(x,117,150,108,i===+o.stage?'#f5d39f':'#e7efe0',20,i===+o.stage?'#c9a56a':'#aec8b1',3)+text(x+75,176,z,'note','text-anchor="middle"')+(i<3?arrow(x+154,171,x+179,171,'#8cae9e',4):'')}).join('')+text(51,276,'Makanan diproses secara mekanik dan kimiawi di organ berbeda.','tiny'),'Diagram urutan saluran pencernaan manusia');}
});

add('gasexchange',{module:3,name:'Oksigen berpindah melalui insang atau paru',emoji:'🫁',tag:'Pernapasan',
 observe:'Oksigen berdifusi dari lingkungan ke darah jika ada perbedaan tekanan parsial. Karbon dioksida berdifusi sebaliknya.',
 question:'Mengapa insang ikan cocok mengambil oksigen terlarut dari air?',
 concept:'Permukaan insang dan alveolus luas, tipis, dan banyak pembuluh kapiler, sehingga pertukaran gas berlangsung efisien melalui difusi.',
 derivation:['Udara atau air bersentuhan dengan permukaan pertukaran gas.','O₂ bergerak mengikuti gradien tekanan parsial menuju darah; CO₂ bergerak ke arah sebaliknya.','Darah mengangkut O₂ ke jaringan yang membutuhkannya.'],
 assumption:'Skema gradien gas kualitatif; tidak menampilkan nilai tekanan parsial atau struktur anatomi yang sesuai skala.',
 controls:[C('organ','Organ',[['lungs','Alveolus manusia'],['gills','Insang ikan']],'gills')],
 calc:o=>explain(o.organ==='gills'?'Insang menyerap O₂ dari air':'Alveolus menyerap O₂ dari udara','O₂ dan CO₂ berpindah melewati permukaan pertukaran gas yang tipis melalui difusi.'),
 render:(o,t)=>svg(foreground('Difusi O₂ dan CO₂ berlawanan arah')+rect(90,90,270,190,'#b7dfeb',25)+rect(432,90,240,190,'#f7cbc6',25)+text(165,145,o.organ==='gills'?'Air di insang':'Udara alveolus','note')+text(497,145,'Darah kapiler','note')+arrow(340,177,457,177,'#6bb3a5',6)+arrow(457,223,340,223,'#d88e7a',6)+text(387,160,'O₂ →','note')+text(385,252,'← CO₂','note'),'Difusi gas dari air atau udara menuju kapiler dan sebaliknya')
});

add('vascular',{module:4,name:'Xilem dan floem membawa zat berbeda',emoji:'🌳',tag:'Tumbuhan',
 observe:'Xilem terutama mengangkut air dan mineral dari akar ke bagian atas. Floem mengangkut hasil fotosintesis dari organ sumber ke organ tujuan, arahnya sesuai kebutuhan.',
 question:'Jika daun menghasilkan gula, jaringan apa mengangkutnya ke akar penyimpan?',
 concept:'Xilem terutama untuk air dan mineral, didorong antara lain oleh transpirasi. Floem mengalirkan gula dan bahan organik dari sumber (source) ke tujuan (sink).',
 derivation:['Akar menyerap air dan mineral dari tanah.','Air dapat bergerak ke daun melalui xilem, ditarik oleh transpirasi.','Gula hasil fotosintesis diangkut dalam floem ke bagian yang tumbuh atau menyimpan cadangan.'],
 assumption:'Panah xilem ke atas dan floem ke bawah merupakan contoh daun→akar; aliran floem sesungguhnya dapat menuju atas atau bawah bergantung posisi sumber–tujuan.',
 controls:[C('system','Jaringan yang ditandai',[['xylem','Xilem'],['phloem','Floem']],'xylem')],
 calc:o=>explain(o.system==='xylem'?'Xilem: air dan mineral':'Floem: gula hasil fotosintesis',o.system==='xylem'?'Contoh utama: aliran air dari akar ke daun.':'Contoh: gula yang dibuat daun dikirim ke akar penyimpan.'),
 render:(o,t)=>svg(foreground('Dua jaringan, dua tugas utama')+`<path d="M366 274V118Q321 89 287 84M366 125Q426 101 476 91" stroke="#7aa67d" fill="none" stroke-width="16" stroke-linecap="round"/>`+line(350,254,350,114,o.system==='xylem'?'#5aa9c6':'#c4d2ce',10)+line(381,114,381,254,o.system==='phloem'?'#d89964':'#c4d2ce',10)+arrow(350,234,350,145,'#5aa9c6',5)+arrow(381,144,381,238,'#d89964',5)+text(125,124,'Xilem: air ↑','note')+text(449,218,'Floem: gula ↓ (contoh)','note')+text(297,310,'akar','tiny'),'Penampang jalur transpor xilem dan floem dalam tumbuhan')
});

add('mitosis',{module:5,name:'Sel membelah: mitosis atau meiosis',emoji:'🧫',tag:'Sel dan genetika',
 observe:'Mitosis mempertahankan jumlah kromosom pada dua sel anak; meiosis menghasilkan sel haploid melalui dua pembelahan, disertai rekombinasi.',
 question:'Mengapa mitosis cocok untuk pertumbuhan dan perbaikan jaringan tubuh?',
 concept:'Mitosis menghasilkan dua sel anak dengan jumlah kromosom sama seperti induk (dalam pembelahan biasa). Meiosis membentuk sel haploid untuk reproduksi seksual.',
 derivation:['DNA digandakan terlebih dahulu sebelum pembelahan.','Pada mitosis, kromatid saudara dipisahkan sehingga dua sel anak menerima set kromosom yang setara.','Pada meiosis, homolog berpisah di meiosis I dan kromatid saudara di meiosis II, menghasilkan sel haploid.'],
 assumption:'Gambar menyederhanakan kromosom dan tidak menunjukkan semua fase pembelahan atau crossing-over. Empat sel adalah hasil umum meiosis satu sel diploid, tidak selalu empat gamet fungsional.',
 controls:[C('type','Jenis pembelahan',[['mitosis','Mitosis'],['meiosis','Meiosis']],'mitosis')],
 calc:o=>explain(o.type==='mitosis'?'1 sel → 2 sel dengan jumlah kromosom setara':'1 sel → 4 sel haploid (contoh)',o.type==='mitosis'?'Mitosis umum pada pertumbuhan dan perbaikan jaringan.':'Meiosis mengurangi jumlah kromosom hingga setengah dalam proses pembentukan sel kelamin.'),
 render:(o,t)=>svg(foreground('Perhatikan jumlah hasil dan kromosom')+circ(125,171,56,'#e6cce3')+text(104,181,'2n','note')+arrow(197,171,293,171,'#8bafa0',5)+(o.type==='mitosis'?[100,231].map(y=>circ(473,y,44,'#d3e8d7')+text(455,y+7,'2n','note')).join(''):[90,147,218,276].map(y=>circ(470,y,25,'#d7e8d7')+text(457,y+6,'n','note')).join(''))+text(100,253,'Sel induk','tiny')+text(498,316,o.type==='mitosis'?'Dua sel anak':'Empat sel haploid','tiny'),'Hasil pembelahan mitosis dan meiosis dengan notasi kromosom n dan 2n')
});

add('biodiversity',{module:2,name:'Tiga tingkat keanekaragaman',emoji:'🦋',tag:'Keanekaragaman hayati',
 observe:'Genetik: variasi dalam satu spesies. Spesies: jenis berbeda. Ekosistem: perbedaan habitat dan komunitas.',
 question:'Berbagai varietas padi termasuk keanekaragaman genetik, spesies, atau ekosistem?',
 concept:'Biodiversitas dapat dibahas pada tingkat genetik, spesies, dan ekosistem. Perbedaan varietas dalam satu spesies tidak sama dengan perbedaan ekosistem.',
 derivation:['Periksa apakah contoh membandingkan individu/varietas dalam spesies yang sama. Jika ya, tingkat genetik.','Jika membandingkan beberapa spesies berbeda, tingkat spesies.','Jika membandingkan hutan bakau, savana, dan terumbu karang, tingkat ekosistem.'],
 assumption:'Ilustrasi menggunakan label kategori; bukan ukuran biodiversitas kuantitatif.',
 controls:[C('level','Tingkat variasi',[['gene','Genetik'],['species','Spesies'],['ecosystem','Ekosistem']],'gene')],
 calc:o=>explain(({gene:'Genetik: varietas padi',species:'Spesies: padi, jagung, kelapa',ecosystem:'Ekosistem: mangrove, savana, terumbu karang'})[o.level],'Tingkat yang berbeda tidak bisa disimpulkan hanya dari besarnya ukuran atau jumlah individu.'),
 render:(o,t)=>{const opts=o.level==='gene'?['Padi A','Padi B','Padi C']:o.level==='species'?['Padi','Jagung','Kelapa']:['Mangrove','Savana','Terumbu'];return svg(foreground('Beda tingkat → beda hal yang dibandingkan')+opts.map((name,i)=>rect(76+i*209,100,166,138,i===1?'#f7e1b5':'#e0eee0',20,'#bdd1ba',3)+text(159+i*209,179,name,'note','text-anchor="middle"')).join('')+text(120,288,'Coba pindah tingkat untuk membedakan contohnya.','note'),'Tiga contoh pada tingkat keanekaragaman genetik, spesies, ekosistem');}
});

add('conservation',{module:13,name:'Melindungi spesies: in situ atau ex situ',emoji:'🌳',tag:'Konservasi',
 observe:'In situ menjaga spesies di habitat aslinya. Ex situ menjaga organisme atau materi genetiknya di luar habitat aslinya.',
 question:'Apakah bank benih termasuk konservasi in situ atau ex situ?',
 concept:'Konservasi in situ melindungi populasi beserta lingkungan alami; ex situ dapat mencakup bank benih, kebun raya, dan penangkaran terkelola.',
 derivation:['Tanyakan: apakah perlindungan dilakukan di habitat alami? Jika ya, in situ.','Jika penyimpanan/pemeliharaan dilakukan di tempat lain, ex situ.','Kedua strategi bisa saling melengkapi untuk mengurangi risiko kepunahan.'],
 assumption:'Gambar hanya menunjukkan contoh strategi; efektivitas tergantung pengelolaan dan kondisi ekologis.',
 controls:[C('type','Jenis konservasi',[['in','In situ (di habitat asli)'],['ex','Ex situ (di luar habitat asli)']],'in')],
 calc:o=>explain(o.type==='in'?'In situ: kawasan konservasi habitat asli':'Ex situ: bank benih atau kebun raya','Memindahkan seluruh populasi dari habitatnya tidak sama dengan menjaga habitat alaminya.'),
 render:(o,t)=>svg(foreground('Tempat perlindungan menjadi pembeda')+(o.type==='in'?`<path d="M60 271L180 91L255 271Z" fill="#9ccc9c"/><path d="M221 271L342 67L451 271Z" fill="#79ae86"/>`+text(474,176,'Hutan lindung','note'):rect(84,103,570,170,'#e1eadd',20)+Array.from({length:4},(_,i)=>rect(123+i*119,144,82,84,'#f2e5bb',8,'#b5c5a2',2)).join('')+text(480,91,'Bank benih','note'))+text(132,321,o.type==='in'?'Habitat alami dilindungi':'Materi genetik disimpan di luar habitat','tiny'),'Contoh strategi konservasi di habitat asli atau di fasilitas penyimpanan')
});

add('symbiosis',{module:13,name:'Hubungan dua makhluk hidup',emoji:'🐝',tag:'Ekologi',
 observe:'Bedakan akibat hubungan terhadap tiap pihak: menguntungkan, netral, atau merugikan. Jangan menebak dari kedekatan fisik saja.',
 question:'Lebah mendapat nektar, bunga terbantu penyerbukan. Bagaimana dampaknya pada masing-masing?',
 concept:'Mutualisme (+,+), komensalisme (+,0), parasitisme (+,−). Hubungan tergantung konteks organisme yang terlibat.',
 derivation:['Tentukan manfaat atau kerugian pada organisme A.','Lakukan hal yang sama untuk organisme B.','Bandingkan tanda dampaknya: (+,+), (+,0), (+,−).'],
 assumption:'Klasifikasi dampak merupakan penyederhanaan interaksi ekologis; dampaknya dapat berubah bergantung lingkungan dan skala waktu.',
 controls:[C('relation','Jenis interaksi',[['mutual','Lebah dan bunga'],['commensal','Anggrek epifit pada pohon'],['parasite','Benalu dan inang']],'mutual')],
 calc:o=>explain(({mutual:'Mutualisme (+,+)',commensal:'Komensalisme (+,0)',parasite:'Parasitisme (+,−)'})[o.relation],({mutual:'Lebah memperoleh nektar, bunga terbantu penyerbukan.',commensal:'Anggrek memperoleh tempat tumbuh tanpa mengambil sari makanan pohon sebagai parasit.',parasite:'Benalu memperoleh sumber daya dari inang yang dirugikan.'})[o.relation]),
 render:(o,t)=>svg(foreground('Lihat dampak terhadap kedua pihak')+rect(88,98,225,142,'#e2efdc',25)+rect(439,98,225,142,'#f8ead4',25)+text(158,162,'Organisme A','note')+text(508,162,'Organisme B','note')+text(178,212,'+','note')+text(528,212,o.relation==='mutual'?'+':o.relation==='commensal'?'0':'−','note')+text(155,284,'Tanda menunjukkan dampak ekologis, bukan jumlah individu.','tiny'),'Dua organisme dengan simbol dampak positif netral negatif')
});

add('sensor',{module:14,name:'Bagaimana kamera mengamati tanaman?',emoji:'📷',tag:'Teknologi lingkungan',
 observe:'Kamera multispektral merekam pantulan pada beberapa panjang gelombang. Vegetasi sering memantulkan dekat-inframerah lebih tinggi daripada merah tampak.',
 question:'Apakah kamera multispektral membaca jumlah kromosom tanaman secara langsung dari udara?',
 concept:'Indeks seperti NDVI menggunakan pantulan dekat-inframerah (NIR) dan merah: NDVI = (NIR−Merah)/(NIR+Merah). Nilainya terkait karakteristik vegetasi, bukan diagnosis tunggal.',
 derivation:['Sensor mengukur intensitas radiasi elektromagnetik yang dipantulkan.','Gabungkan band merah dan NIR untuk menghitung NDVI.','Interpretasikan hasil bersama kalibrasi, cuaca, jenis vegetasi, dan informasi lapangan.'],
 assumption:'Nilai reflektansi adalah contoh buatan; NDVI bukan ukuran langsung kesehatan, hasil panen atau jumlah kromosom. Sinar tampak dan inframerah dekat adalah bagian spektrum elektromagnetik.',
 controls:[S('red','Reflektansi merah',10,70,5,20,'%'),S('nir','Reflektansi NIR',10,80,5,60,'%')],
 calc:o=>explain(`NDVI contoh = ${n((o.nir-o.red)/(o.nir+o.red))}`,`(${o.nir} − ${o.red}) / (${o.nir} + ${o.red}) = ${n((o.nir-o.red)/(o.nir+o.red))}. Untuk data nyata, koreksi atmosfer dan kalibrasi diperlukan.`),
 render:(o,t)=>svg(foreground('Dua kanal spektral dibandingkan')+rect(155,122,180,200,'#d9ebd7',10)+rect(425,122,180,200,'#dfecdb',10)+rect(185,295-o.red*2,120,o.red*2,'#d77972',6)+rect(455,295-o.nir*2,120,o.nir*2,'#8d9dc6',6)+text(176,85,`Merah ${o.red}%`,'note')+text(445,85,`NIR ${o.nir}%`,'note'),'Grafik dua band reflektansi merah dan inframerah dekat')
});

add('antibiotic',{module:14,name:'Mengapa antibiotik tidak untuk virus?',emoji:'🦠',tag:'Kesehatan',
 observe:'Antibiotik menargetkan struktur atau proses tertentu pada bakteri. Virus memperbanyak diri dengan memanfaatkan sel inang, sehingga antibiotik biasa tidak mengobati infeksi virus.',
 question:'Mengapa antibiotik untuk flu yang disebabkan virus tidak membantu dan dapat mendorong resistansi bakteri?',
 concept:'Penggunaan antibiotik yang tidak tepat memberi tekanan seleksi pada bakteri yang memiliki ketahanan, tanpa mengatasi penyebab virus.',
 derivation:['Bedakan penyebab infeksi bakteri dan infeksi virus.','Antibiotik efektif terhadap bakteri tertentu bila digunakan sesuai evaluasi klinis.','Penggunaan yang tidak perlu dapat meningkatkan seleksi bakteri resisten dan menimbulkan efek samping.'],
 assumption:'Bagan edukasi umum; keputusan penggunaan antibiotik perlu pemeriksaan medis. Tidak semua infeksi memerlukan antibiotik.',
 controls:[C('germ','Penyebab penyakit',[['virus','Virus penyebab flu'],['bacteria','Bakteri yang rentan antibiotik']],'virus')],
 calc:o=>explain(o.germ==='virus'?'Antibiotik tidak mengobati penyebab virus':'Antibiotik yang sesuai dapat bekerja pada bakteri tertentu',o.germ==='virus'?'Flu biasa terutama disebabkan virus; penanganan tergantung gejala dan kondisi pasien.':'Pilihan antibiotik, dosis, dan durasi harus sesuai tenaga kesehatan.'),
 render:(o,t)=>svg(foreground('Bakteri dan virus adalah dua jenis agen berbeda')+circ(245,169,77,o.germ==='bacteria'?'#abcfae':'#d9b2cd','#a57eab',4)+text(211,176,o.germ==='bacteria'?'Bakteri':'Virus','note')+rect(452,111,202,119,'#f5deab',24,'#d6b985',2)+text(477,176,'Antibiotik','note')+arrow(460,260,450,238,'#b3a787',3)+text(100,314,o.germ==='virus'?'Target antibiotik berbeda dari komponen virus.':'Antibiotik dipilih sesuai bakteri dan indikasi.','tiny'),'Perbandingan antibiotik dengan bakteri atau virus secara konseptual')
});

add('radiation',{module:10,name:'Kalor Matahari melalui ruang hampa',emoji:'🌞',tag:'Perpindahan kalor',
 observe:'Cahaya Matahari menempuh ruang angkasa yang hampir hampa sebagai radiasi elektromagnetik, tanpa memerlukan udara pengantar.',
 question:'Mengapa energi Matahari tetap bisa sampai ke Bumi walau ruang antarplanet nyaris hampa?',
 concept:'Radiasi elektromagnetik dapat merambat melalui ruang hampa. Konduksi membutuhkan interaksi langsung dalam zat; konveksi membutuhkan aliran fluida.',
 derivation:['Energi Matahari dipancarkan sebagai gelombang elektromagnetik.','Gelombang elektromagnetik dapat melintasi ruang hampa.','Ketika diserap permukaan Bumi, radiasi meningkatkan energi internal atau digunakan dalam proses lain.'],
 assumption:'Skema tidak berskala; energi Matahari terdiri atas berbagai panjang gelombang dan intensitas berkurang dengan jarak.',
 controls:[C('medium','Ruang antara benda',[['vacuum','Ruang hampa'],['air','Ada udara']],'vacuum')],
 calc:o=>explain('Radiasi tetap dapat lewat',o.medium==='vacuum'?'Radiasi elektromagnetik tidak memerlukan materi untuk merambat.':'Radiasi tetap ada meskipun udara juga dapat mentransfer kalor melalui mekanisme lain.'),
 render:(o,t)=>svg(foreground('Radiasi tidak memerlukan udara')+circ(140,160,75,'#f6d376')+circ(620,160,66,'#8dbdd6')+Array.from({length:5},(_,i)=>arrow(234,90+i*33,536,90+i*33,'#deab62',3)).join('')+text(83,284,'Matahari','note')+text(587,276,'Bumi','note')+text(330,65,o.medium==='vacuum'?'Ruang hampa':'Ruang berisi udara','note'),'Radiasi elektromagnetik merambat dari Matahari ke Bumi')
});

add('rabies',{module:14,name:'Langkah awal setelah gigitan berisiko rabies',emoji:'🩹',tag:'Keselamatan',
 observe:'Gigitan atau cakaran hewan yang diduga rabies perlu ditangani segera, bahkan sebelum gejala muncul.',
 question:'Apa dua tindakan pertama setelah kemungkinan pajanan rabies?',
 concept:'Cuci luka segera dengan sabun dan air mengalir sekitar 15 menit, lalu cari pertolongan medis sesegera mungkin untuk penilaian profilaksis pascapajanan.',
 derivation:['Luka gigitan/cakaran dicuci segera dan menyeluruh menggunakan sabun serta air mengalir.','Cari layanan kesehatan segera untuk penilaian risiko, vaksin rabies, dan imunoglobulin bila diperlukan.','Jangan menunggu gejala; rabies yang sudah bergejala hampir selalu fatal.'],
 assumption:'Panduan edukasi dasar, tidak menggantikan penilaian klinis dan protokol kesehatan setempat; semua pajanan berisiko perlu diperiksa.',
 controls:[C('stage','Langkah',[['wash','1. Cuci luka'],['care','2. Cari pertolongan medis']],'wash')],
 calc:o=>explain(o.stage==='wash'?'Segera bersihkan luka dengan sabun dan air':'Segera datang ke layanan kesehatan',o.stage==='wash'?'Pembersihan luka segera dapat mengurangi risiko pajanan.':'Tenaga kesehatan menilai kebutuhan vaksin dan imunoglobulin pascapajanan.'),
 render:(o,t)=>svg(foreground('Jangan menunggu gejala')+rect(95,102,241,151,o.stage==='wash'?'#daeee5':'#f6efe1',20)+text(125,174,'Cuci luka','note')+rect(414,102,241,151,o.stage==='care'?'#daeee5':'#f6efe1',20)+text(448,174,'Ke layanan','note')+text(447,199,'kesehatan','tiny')+arrow(341,174,409,174,'#69a48c',4)+text(141,301,'Penanganan awal perlu segera dilakukan.','note'),'Dua tahap awal pajanan rabies: cuci luka dan cari pertolongan medis')
});


add('waterfilter',{module:14,name:'Mengapa saringan menahan partikel?',emoji:'💧',tag:'Teknologi air',observe:'Partikel yang lebih besar daripada bukaan pori dapat tertahan; air dan zat terlarut kecil mungkin tetap lewat.',question:'Apakah filter berpori halus otomatis menghilangkan semua zat terlarut dan mikroorganisme?',concept:'Filtrasi menyisihkan bahan berdasarkan ukuran pori, interaksi media, dan kondisi aliran. Filtrasi biasa tidak otomatis menjamin air bebas patogen atau bahan kimia terlarut.',derivation:['Air kotor mengandung partikel dari berbagai ukuran.','Media berpori dapat menahan sebagian partikel, bergantung ukuran dan sifat media.','Untuk air minum aman, pengolahan perlu sesuai jenis pencemar, termasuk disinfeksi bila diperlukan.'],assumption:'Ukuran pada gambar tidak berskala; hasil filtrasi nyata bergantung pori, kontak, penyumbatan, dan kualitas air masuk.',controls:[C('pore','Ukuran pori relatif',[['large','Besar'],['small','Halus']],'small')],calc:o=>explain(o.pore==='small'?'Lebih banyak partikel besar tertahan':'Lebih banyak partikel dapat lolos','Air yang tampak bening belum tentu aman diminum.'),render:(o,t)=>svg(foreground('Filtrasi ≠ jaminan sterilisasi')+rect(160,140,440,19,'#b4a88b',3)+Array.from({length:16},(_,i)=>circ(196+i*25,111,7+(i%3)*3,'#b98a5d')).join('')+Array.from({length:o.pore==='small'?5:11},(_,i)=>circ(260+i*27,217,5+(i%2)*4,'#b98a5d')).join('')+arrow(394,68,394,128,'#6ab1c0',4)+arrow(394,168,394,267,'#6ab1c0',4)+text(112,65,'air + partikel','note')+text(454,190,'media berpori','tiny')+text(118,310,'Sebagian partikel tertahan · zat terlarut bisa lewat','tiny'),'Aliran air melewati media berpori yang menyaring sebagian partikel')});

add('solar',{module:14,name:'Panel surya mengubah energi apa?',emoji:'☀️',tag:'Energi terbarukan',observe:'Foton cahaya diserap sel fotovoltaik dan menghasilkan beda potensial listrik; energi keluaran lebih kecil daripada energi cahaya masuk.',question:'Apa perubahan energi utama pada panel surya fotovoltaik?',concept:'Sel fotovoltaik mengubah sebagian energi radiasi cahaya menjadi energi listrik melalui efek fotovoltaik, bukan menjadi listrik dari panas semata.',derivation:['Cahaya mengenai bahan semikonduktor dalam sel surya.','Penyerapan foton dapat menghasilkan pasangan pembawa muatan dan mendorong pemisahan muatan pada sambungan.','Rangkaian luar menerima energi listrik; sisanya tidak menjadi keluaran listrik yang diinginkan.'],assumption:'Skema proses tanpa model semikonduktor rinci; bukan prediksi daya panel nyata.',controls:[C('light','Penyinaran',[['sunny','Cukup cahaya'],['shade','Lebih ternaungi']],'sunny')],calc:o=>explain('Energi cahaya → energi listrik',o.light==='sunny'?'Dengan faktor lain sama, tersedia lebih banyak energi cahaya untuk dikonversi.':'Naungan biasanya mengurangi daya listrik yang dihasilkan.'),render:(o,t)=>svg(foreground('Efek fotovoltaik')+circ(150,100,51,o.light==='sunny'?'#f4d077':'#dfd5b4')+Array.from({length:4},(_,i)=>arrow(208,105+i*26,365,160+i*10,'#d8a76e',3)).join('')+`<path d="M330 210L520 210L568 274L378 274Z" fill="#6d9cc6" stroke="#486e98" stroke-width="4"/>`+arrow(551,240,657,240,'#4c9a80',5)+text(531,197,'listrik →','note')+text(93,245,'cahaya','tiny'),'Panel fotovoltaik menerima cahaya dan menghasilkan listrik')});

add('bioremediation',{module:14,name:'Mikroorganisme mengurai pencemar',emoji:'🦠',tag:'Pengolahan lingkungan',observe:'Mikroorganisme tertentu dapat mengubah atau mendegradasi kontaminan melalui proses metabolisme.',question:'Apakah semua pencemar dapat dihancurkan sepenuhnya oleh setiap mikroorganisme?',concept:'Bioremediasi menggunakan aktivitas organisme, terutama mikroorganisme, untuk mengurangi atau mengubah bahan pencemar dalam kondisi yang sesuai.',derivation:['Kenali jenis polutan dan kemampuan mikroba yang relevan.','Sediakan kondisi lingkungan yang menunjang metabolisme (misalnya oksigen, nutrien, pH yang sesuai).','Uji konsentrasi pencemar sebelum–sesudah serta kemungkinan produk hasil degradasi.'],assumption:'Partikel pencemar yang berkurang di gambar bersifat ilustratif, bukan data efektivitas pengolahan atau jaminan seluruh polutan hilang.',controls:[C('condition','Kondisi lingkungan',[['good','Sesuai kebutuhan mikroba'],['poor','Tidak sesuai']],'good')],calc:o=>explain(o.condition==='good'?'Penguraian dapat berlangsung lebih baik':'Penguraian dapat terhambat','Perlu jenis mikroba, oksigen/nutrisi, dan pemantauan kontaminan yang sesuai.'),render:(o,t)=>svg(foreground('Polutan diubah lewat aktivitas mikroba')+rect(94,108,560,169,'#c5e7db',22)+Array.from({length:o.condition==='good'?10:19},(_,i)=>circ(145+(i*53)%460,160+(i*37)%91,9,'#c18c77')).join('')+Array.from({length:7},(_,i)=>`<ellipse cx="${145+i*66}" cy="210" rx="16" ry="11" fill="#76b09c" stroke="#4e8c7b" stroke-width="2"/>`).join('')+text(141,74,'mikroba + polutan','note')+text(403,311,'kondisi memengaruhi proses','tiny'),'Mikroorganisme dan partikel polutan dalam lingkungan cair')});

add('waterborne',{module:14,name:'Mengapa air tercemar bisa menularkan penyakit?',emoji:'🚰',tag:'Kesehatan lingkungan',observe:'Tinja dari manusia/hewan dapat membawa mikroorganisme patogen ke air. Air yang tercemar fecal-oral dapat menyebabkan penyakit saluran pencernaan.',question:'Mengapa air yang terlihat jernih belum tentu bebas penyakit?',concept:'Penyakit yang ditularkan melalui air terkontaminasi dapat dicegah dengan sanitasi, pengolahan air aman, dan kebersihan.',derivation:['Sumber kontaminasi membawa patogen ke air.','Air atau makanan yang tercemar masuk melalui mulut.','Perbaikan sanitasi dan pengolahan/disinfeksi air mengurangi risiko penularan.'],assumption:'Alur ini bukan hasil uji mikrobiologi; air tampak jernih tidak membuktikan bebas patogen.',controls:[C('treatment','Tindakan',[['raw','Air tidak diolah'],['treated','Air diolah sesuai standar']],'raw')],calc:o=>explain(o.treatment==='raw'?'Risiko kontaminasi perlu diperiksa':'Pengolahan yang tepat menurunkan risiko','Keamanan harus dipastikan melalui proses dan pemeriksaan kualitas yang sesuai.'),render:(o,t)=>svg(foreground('Jalur penularan dan pencegahannya')+rect(74,126,162,113,'#ebd9bb',19)+rect(304,126,162,113,'#b9dce9',19)+rect(534,126,162,113,'#e9ead3',19)+text(109,180,'Sumber','note')+text(321,180,'Air','note')+text(560,180,'Manusia','note')+arrow(239,182,297,182,'#d58e72',4)+arrow(469,182,526,182,'#d58e72',4)+text(113,283,'Sanitasi dan pengolahan air memutus jalur penularan.','tiny'),'Rute pencemaran sumber ke air ke manusia')});

add('vector',{module:14,name:'Memutus siklus nyamuk penyebab DBD',emoji:'🦟',tag:'Kesehatan masyarakat',observe:'Nyamuk Aedes berkembang biak melalui fase telur, larva, pupa, dewasa; menghilangkan genangan yang menjadi tempat perindukan membantu mencegah DBD.',question:'Mengapa membersihkan tempat penampungan air lebih berkelanjutan daripada hanya menyemprot nyamuk dewasa?',concept:'Pengendalian vektor terpadu mencakup pemberantasan sumber perindukan, perlindungan individu, pemantauan, dan pengendalian tambahan sesuai kebutuhan.',derivation:['Kenali habitat perindukan nyamuk penular.','Kurangi sumber larva dengan menguras/menutup/mendaur ulang tempat air sesuai program setempat.','Pantau populasi, gunakan cara lain secara terpadu untuk mengurangi ketergantungan insektisida.'],assumption:'Skema siklus hidup sederhana; tidak menampilkan durasi pasti atau angka penurunan kasus.',controls:[C('stage','Tahap yang disasar',[['larva','Larva di genangan'],['adult','Nyamuk dewasa']],'larva')],calc:o=>explain(o.stage==='larva'?'Kurangi tempat perindukan':'Lindungi diri dari gigitan','Strategi terpadu perlu menangani banyak tahap siklus hidup, bukan satu cara saja.'),render:(o,t)=>svg(foreground('Putus satu bagian siklus hidup')+rect(104,133,235,121,o.stage==='larva'?'#f5d7a7':'#d0e8ea',24)+rect(438,133,235,121,o.stage==='adult'?'#f5d7a7':'#d0e8ea',24)+text(156,194,'Larva / pupa','note')+text(490,194,'Dewasa','note')+arrow(344,190,430,190,'#7ba58e',4)+text(164,305,'Kurangi genangan · Hindari gigitan · Pantau vektor','tiny'),'Tahap larva dan dewasa nyamuk untuk pengendalian vektor terpadu')});

add('airquality',{module:14,name:'Partikel halus PM2,5 di udara',emoji:'🌫️',tag:'Kualitas udara',observe:'PM2,5 adalah partikel yang diameternya aerodinamis ≤2,5 mikrometer. Sensor melaporkan konsentrasinya, umumnya dalam µg/m³.',question:'Apakah angka PM2,5 menunjukkan suhu udara atau konsentrasi partikel halus?',concept:'PM2,5 adalah fraksi partikel tersuspensi di udara yang berukuran sangat kecil. Paparan dapat merugikan kesehatan; masker respirator partikulat yang sesuai dan rapat dapat mengurangi partikel yang terhirup.',derivation:['Sensor PM2,5 memperkirakan konsentrasi partikel halus dalam volume udara.','Konsentrasi dan lama paparan sama-sama relevan terhadap dosis yang terhirup.','Tindakan perlindungan meliputi mengurangi paparan dan memakai respirator partikulat sesuai kebutuhan serta kecocokan.'],assumption:'Titik dalam gambar hanyalah ilustrasi jumlah relatif, tidak menghasilkan angka konsentrasi nyata atau klaim mutu masker tertentu.',controls:[C('air','Kondisi contoh',[['high','Banyak partikel'],['low','Lebih sedikit partikel']],'high')],calc:o=>explain(o.air==='high'?'Paparan partikel lebih besar':'Paparan partikel lebih rendah','PM2,5 adalah parameter konsentrasi partikel berukuran kecil, bukan kadar karbon dioksida atau suhu.'),render:(o,t)=>svg(foreground('Partikel halus tersuspensi dalam udara')+rect(86,66,593,234,'#ecf1ed',25)+Array.from({length:o.air==='high'?45:11},(_,i)=>circ(119+(i*73)%520,104+(i*47)%171,2+i%3*2,'#a5b3b0')).join('')+text(137,322,o.air==='high'?'Lebih banyak partikel per volume udara':'Lebih sedikit partikel per volume udara','note'),'Sketsa partikel halus PM2.5 dalam volume udara')});

add('handwash',{module:14,name:'Mengapa sabun membantu cuci tangan?',emoji:'🧼',tag:'Kebersihan',observe:'Sabun membantu melepaskan minyak, kotoran, dan banyak mikroorganisme dari kulit agar dapat dibilas dengan air.',question:'Apakah sabun harus membunuh semua mikroorganisme untuk membantu membersihkan tangan?',concept:'Molekul sabun memiliki bagian suka air dan suka minyak. Bersama gosokan dan bilasan, sabun mengangkat kotoran dan mikroba; pada banyak virus berselubung, sabun juga dapat merusak selubung lipid.',derivation:['Bagian hidrofobik molekul sabun berinteraksi dengan minyak/kotoran.','Bagian hidrofilik berinteraksi dengan air; penggosokan membantu melepaskan kotoran.','Air mengalir membilas partikel dan mikroba dari kulit.'],assumption:'Skema bukan representasi molekul sesuai skala; praktik cuci tangan perlu durasi dan teknik yang dianjurkan lembaga kesehatan.',controls:[C('soap','Kondisi',[['yes','Dengan sabun dan air'],['no','Air tanpa sabun']],'yes')],calc:o=>explain(o.soap==='yes'?'Pengangkatan kotoran berminyak lebih efektif':'Sebagian kotoran berminyak lebih sulit diangkat','Sabun + air mengalir dan gosokan membantu mengurangi kontaminasi pada tangan.'),render:(o,t)=>svg(foreground('Sabun membantu melepaskan minyak dan kotoran')+rect(112,110,503,169,'#e8d6ba',28)+Array.from({length:o.soap==='yes'?8:24},(_,i)=>circ(155+(i*61)%423,158+(i*39)%94,7,'#a8a09c')).join('')+(o.soap==='yes'?Array.from({length:7},(_,i)=>circ(154+i*60,126,10,'#f8fcfc','#b5d8d5',2)).join(''):'')+text(148,72,o.soap==='yes'?'Sabun + air + gosokan':'Air saja','note'),'Kotoran menempel pada permukaan kulit dengan atau tanpa sabun')});

add('biogas',{module:14,name:'Digester anaerob menghasilkan biogas',emoji:'♻️',tag:'Teknologi lingkungan',observe:'Mikroorganisme menguraikan bahan organik dalam kondisi tanpa oksigen bebas. Gas yang terkumpul umumnya mengandung metana dan karbon dioksida.',question:'Mengapa reaktor limbah anaerob bisa menjadi sumber bahan bakar?',concept:'Pencernaan anaerob (anaerobic digestion) mengubah sebagian bahan organik menjadi biogas, terutama CH₄ dan CO₂, melalui beberapa kelompok mikroorganisme.',derivation:['Bahan organik masuk ke reaktor tertutup.','Tahapan mikrobiologis menguraikan molekul organik menjadi senyawa yang dapat digunakan metanogen.','Metana dalam biogas dapat dimanfaatkan sebagai sumber energi setelah penanganan yang sesuai.'],assumption:'Model tidak memperkirakan komposisi atau produksi gas, dan operasi biogas perlu kontrol keselamatan metana/H₂S.',controls:[C('oxygen','Kondisi reaktor',[['off','Anaerob'],['on','Ada oksigen']],'off')],calc:o=>explain(o.oxygen==='off'?'Metanogenesis dapat terjadi pada kondisi sesuai':'Proses mikroba dapat bergeser dari metanogenesis','Digester anaerob harus dijalankan dalam kondisi sesuai untuk pembentukan biogas.'),render:(o,t)=>svg(foreground('Bahan organik → reaktor → biogas')+rect(236,132,287,147,'#d4c5ab',28,'#a89575',4)+Array.from({length:o.oxygen==='off'?11:3},(_,i)=>circ(290+(i*43)%170,100-(i*16)%70,6+i%2*4,'#a7d8ce','#7eaf9e',2)).join('')+text(94,173,'Limbah organik','note')+arrow(206,183,235,183,'#ab9b76',4)+arrow(526,123,615,73,'#69a690',4)+text(590,60,'Biogas','note'),'Reaktor digester dengan bahan organik dan gelembung biogas')});

add('barcoding',{module:14,name:'DNA barcode mengenali organisme',emoji:'🧬',tag:'Biologi molekuler',observe:'Peneliti membandingkan urutan DNA penanda tertentu dengan pustaka referensi untuk membantu identifikasi spesies.',question:'Apa yang dibaca pada DNA barcoding: urutan basa DNA atau warna daun?',concept:'DNA barcoding memakai fragmen genetik standar untuk membedakan taksa tertentu. Hasil harus dibandingkan dengan basis data dan dinilai kualitasnya.',derivation:['Ambil sampel DNA dan analisis daerah penanda yang tepat.','Dapatkan urutan basa A, T, G, C.','Bandingkan dengan referensi; kemiripan sequence mendukung identifikasi, tetapi tidak selalu memastikan sendiri satu spesies.'],assumption:'Urutan DNA pada gambar fiktif dan bukan hasil analisis organisme nyata.',controls:[C('sample','Sampel ilustratif',[['1','Sampel A'],['2','Sampel B']],'1')],calc:o=>explain(o.sample==='1'?'Baca urutan DNA sampel A':'Baca urutan DNA sampel B','Perbedaan urutan penanda dapat membantu identifikasi ketika dibandingkan referensi yang andal.'),render:(o,t)=>svg(foreground('DNA barcoding membandingkan urutan basa')+Array.from({length:12},(_,i)=>rect(84+i*51,143,42,50,['#d9c9e9','#bfe6d9','#f5d59a','#f1c5bb'][((o.sample==='1'?i:i+1)+2)%4],7)+text(98+i*51,175,['A','T','G','C'][(i+(o.sample==='1'?0:1))%4],'note')).join('')+text(100,102,'A, T, G, C adalah jenis basa DNA','note')+text(130,255,'Cocokkan dengan pustaka referensi','tiny'),'Urutan simbol basa DNA untuk dibandingkan sebagai barcode genetika')});

add('bioengineering',{module:14,name:'Bakteri dapat memproduksi protein manusia',emoji:'🧬',tag:'Bioteknologi',observe:'Rekayasa DNA dapat memasukkan informasi genetik untuk protein tertentu ke sel produksi, misalnya mikroorganisme yang kemudian menghasilkan insulin rekombinan.',question:'Mengapa insulin hasil produksi mikroorganisme rekayasa genetik disebut bioteknologi modern?',concept:'Teknologi DNA rekombinan memungkinkan sel produksi membawa dan mengekspresikan gen untuk protein yang dituju, kemudian produk diproses dan dimurnikan.',derivation:['Pilih informasi genetik yang menyandi protein target.','Gunakan sistem ekspresi yang sesuai dalam sel produksi.','Kultur, panen, dan pemurnian menghasilkan protein yang memenuhi standar mutu.'],assumption:'Bagan proses produksi disederhanakan; pembuatan obat memerlukan kontrol dan regulasi ketat.',controls:[C('stage','Tahap ilustratif',[['1','Informasi genetik'],['2','Sel produksi'],['3','Protein dimurnikan']],'2')],calc:o=>explain(({1:'Informasi gen insulin disiapkan',2:'Sel produksi mengekspresikan protein',3:'Protein dimurnikan dan diuji'})[o.stage],'Tidak cukup memasukkan gen saja; ekspresi, pemrosesan, pemurnian, dan pengujian mutu penting.'),render:(o,t)=>svg(foreground('Gen → sel produksi → protein target')+['Gen','Sel produksi','Insulin'].map((name,i)=>rect(51+i*239,129,197,111,String(i+1)===o.stage?'#f4dbac':'#dfece4',17)+text(97+i*239,192,name,'note')+(i<2?arrow(251+i*239,185,284+i*239,185,'#8bae9d',4):'')).join(''),'Tahap informasi genetik sel produksi dan protein insulin')});

add('yogurt',{module:14,name:'Yoghurt: fermentasi asam laktat',emoji:'🥛',tag:'Bioteknologi pangan',observe:'Bakteri asam laktat memanfaatkan gula susu (laktosa) dan menghasilkan asam laktat yang menurunkan pH serta membantu membentuk tekstur yoghurt.',question:'Mengapa susu menjadi lebih asam ketika difermentasi menjadi yoghurt?',concept:'Fermentasi asam laktat oleh bakteri starter menghasilkan asam laktat; proses ini berbeda dengan fermentasi alkohol oleh ragi pada adonan roti.',derivation:['Susu mengandung laktosa sebagai sumber karbohidrat.','Bakteri starter mengolah gula dan menghasilkan asam laktat.','pH menurun dan perubahan protein susu memengaruhi pembentukan tekstur yoghurt.'],assumption:'Keasaman ilustratif dan bukan rekomendasi keamanan/fermentasi rumahan; suhu dan kultur memengaruhi keberhasilan produk.',controls:[C('process','Tahap proses',[['before','Susu awal'],['after','Setelah fermentasi yang sesuai']],'after')],calc:o=>explain(o.process==='after'?'Asam laktat bertambah → susu lebih asam':'Susu sebelum fermentasi','Perubahan keasaman ditunjukkan secara kualitatif, tanpa memperkirakan nilai pH sampel nyata.'),render:(o,t)=>svg(foreground('Laktosa → fermentasi bakteri → asam laktat')+rect(186,100,388,210,o.process==='after'?'#f2ead2':'#f5f4e7',33,'#c8c6b7',4)+Array.from({length:o.process==='after'?22:8},(_,i)=>circ(215+(i*61)%330,153+(i*37)%115,5,'#abbe9d')).join('')+text(307,76,o.process==='after'?'Yoghurt':'Susu','note')+text(266,324,o.process==='after'?'Asam laktat terbentuk':'Laktosa tersedia','note'),'Bakteri dalam susu dan perubahan keasaman pada fermentasi yoghurt')});

add('volcano',{module:12,name:'Magma berubah menjadi lava di permukaan',emoji:'🌋',tag:'Kebumian',observe:'Batuan cair yang masih berada di bawah permukaan disebut magma. Ketika keluar ke permukaan melalui gunung api, disebut lava.',question:'Apakah batuan cair yang telah keluar dari gunung api masih dinamai magma?',concept:'Magma berada di bawah permukaan Bumi; lava ialah magma yang mencapai permukaan. Letusan juga dapat melepaskan gas dan material piroklastik.',derivation:['Proses geologi menghasilkan batuan cair di bagian kerak atau mantel atas.','Magma dapat bergerak naik melalui rekahan dan sistem vulkanik.','Ketika keluar ke permukaan Bumi, batuan cair itu disebut lava.'],assumption:'Potongan gunung api ideal tanpa skala, tidak menunjukkan semua jenis letusan atau prediksi bahaya.',controls:[C('location','Lokasi batuan cair',[['under','Di bawah permukaan'],['above','Sudah keluar permukaan']],'under')],calc:o=>explain(o.location==='under'?'Disebut magma':'Disebut lava','Perubahan istilah ditentukan lokasi batuan cair relatif permukaan Bumi.'),render:(o,t)=>svg(foreground('Lokasi menentukan istilahnya')+`<path d="M180 253L384 78L582 253Z" fill="#acb6a7" stroke="#7e9185" stroke-width="3"/>`+rect(82,252,607,61,'#bf9b7a',0)+`<path d="M370 285L370 166L388 116L406 166L406 285" fill="${o.location==='under'?'#e79b64':'#bdad98'}"/>`+(o.location==='above'?`<path d="M388 115Q337 107 305 148" stroke="#df885b" stroke-width="10" fill="none"/>`:'')+text(455,295,'di bawah: magma','note')+text(93,111,'di luar: lava','note'),'Potongan gunung api menunjukkan magma di bawah dan lava di permukaan')});

add('nasti',{module:4,name:'Gerak nasti tidak ditentukan arah rangsang',emoji:'🌿',tag:'Gerak tumbuhan',observe:'Putri malu menutup anak daunnya setelah disentuh. Arah menutup terutama ditentukan struktur daun, bukan arah datangnya sentuhan.',question:'Apa bedanya tigmonasti dengan tigmotropisme?',concept:'Nasti adalah gerak respons yang arahnya tidak ditentukan arah rangsangan; tropisme merupakan respons pertumbuhan yang arah responsnya ditentukan arah rangsangan.',derivation:['Sentuhan diterima pada organ peka rangsang.','Perubahan turgor sel pada pulvinus dapat memicu lipatan daun dengan cepat.','Ini berbeda dari pembengkokan pertumbuhan jangka panjang pada tropisme.'],assumption:'Sketsa daun menutup tidak menunjukkan mekanisme tekanan turgor terukur dan kecepatan tidak sesuai skala.',controls:[C('touch','Keadaan daun',[['no','Belum disentuh'],['yes','Setelah disentuh']],'no')],calc:o=>explain(o.touch==='yes'?'Daun menutup akibat rangsang sentuhan':'Daun terbuka','Nasti dapat terjadi tanpa memerlukan arah datangnya sentuhan tertentu.'),render:(o,t)=>svg(foreground('Contoh: daun putri malu')+line(344,275,359,92,'#6a9d73',7)+Array.from({length:5},(_,i)=>{let y=119+i*28,w=o.touch==='yes'?15:93;return line(358,y,358-w,y-12,'#7ba66f',5)+line(358,y,358+w,y-12,'#7ba66f',5)}).join('')+text(440,76,o.touch==='yes'?'Anak daun menutup':'Anak daun terbuka','note'),'Daun putri malu pada keadaan sebelum dan setelah sentuhan')});

add('virus',{module:5,name:'Virus memerlukan sel inang',emoji:'🦠',tag:'Mikrobiologi',observe:'Virus membawa materi genetik dalam partikel, tetapi tidak memiliki perangkat sel lengkap untuk memperbanyak diri secara mandiri.',question:'Mengapa virus tidak dapat bereproduksi mandiri seperti bakteri?',concept:'Virus bereplikasi dengan memanfaatkan mesin sel inang. Bakteri adalah organisme seluler prokariotik dengan ribosom dan metabolisme sendiri.',derivation:['Partikel virus memasuki atau mengantarkan materi genetik ke sel inang yang sesuai.','Mesin sel inang dimanfaatkan untuk membuat komponen virus.','Komponen dirakit dan virus baru dapat keluar melalui mekanisme tertentu.'],assumption:'Diagram alur replikasi umum, tidak semua virus memiliki siklus identik; gambar bukan representasi rinci virus tertentu.',controls:[C('stage','Tahap ilustrasi',[['enter','Masuk ke sel inang'],['copy','Komponen virus dibuat'],['exit','Partikel baru keluar']],'enter')],calc:o=>explain(({enter:'Virus memasuki sel',copy:'Replikasi memerlukan sel',exit:'Partikel virus baru terbentuk'})[o.stage],'Ketiadaan ribosom dan mesin metabolisme mandiri membedakan virus dari sel bakteri.'),render:(o,t)=>svg(foreground('Replikasi virus bergantung sel inang')+circ(366,176,115,'#d6e7dc','#8caf9c',4)+Array.from({length:o.stage==='exit'?8:3},(_,i)=>circ(172+(i*89)%400,105+(i*47)%147,13,'#c18baf','#95709a',3)).join('')+text(314,183,'Sel inang','note')+text(100,312,'Tahapan skematis, bukan pembelahan virus sebagai sel','tiny'),'Virus berinteraksi dengan sel inang dalam replikasi')});

add('kidney',{module:3,name:'Ginjal menyaring darah',emoji:'💧',tag:'Sistem ekskresi',observe:'Darah melalui proses filtrasi di glomerulus. Zat yang masih berguna diserap kembali; zat tertentu juga disekresikan ke cairan tubulus.',question:'Mengapa urine akhir tidak sama dengan cairan hasil filtrasi pertama?',concept:'Nefron membentuk urine melalui filtrasi, reabsorpsi, dan sekresi. Penyaringan awal bukan seluruh proses.',derivation:['Darah memasuki glomerulus dan sebagian air serta zat terlarut kecil memasuki kapsula Bowman.','Sepanjang tubulus, air dan zat berguna dapat direabsorpsi.','Zat lain dapat disekresikan, lalu cairan yang tersisa menjadi urine.'],assumption:'Alur sederhana; lokasi serta besar pengangkutan tiap zat berbeda, dan zat tertentu tidak bebas terfiltrasi.',controls:[C('stage','Proses utama',[['filter','1 · Filtrasi'],['reabsorb','2 · Penyerapan kembali'],['secrete','3 · Sekresi dan urine']],'filter')],calc:o=>explain(({filter:'Filtrasi glomerulus',reabsorb:'Reabsorpsi pada tubulus',secrete:'Sekresi dan pembentukan urine akhir'})[o.stage],'Ginjal menjaga keseimbangan air, ion, dan pembuangan sisa metabolisme.'),render:(o,t)=>svg(foreground('Nefron · gambaran alur, bukan anatomi berskala')+circ(170,132,47,o.stage==='filter'?'#eebca2':'#f3dfc5','#b88773',4)+text(140,138,'Darah','note')+arrow(217,132,343,132,'#c58a71',4)+rect(338,99,175,68,o.stage==='reabsorb'?'#d0ead5':'#e6eee0',22)+text(353,139,'Tubulus','note')+arrow(514,132,634,132,'#74af9c',4)+rect(608,112,106,40,o.stage==='secrete'?'#b6dfe4':'#e9ece4',12)+text(621,137,'Urine','tiny')+text(124,247,'Filtrasi','note')+text(331,247,'Reabsorpsi','note')+text(563,247,'Sekresi','note'),'Aliran penyaringan darah dan pembentukan urine di nefron')});

add('thermoregulation',{module:3,name:'Mengapa kita berkeringat?',emoji:'🌡️',tag:'Pengaturan suhu',observe:'Ketika keringat menguap dari kulit, diperlukan energi kalor yang diambil antara lain dari permukaan tubuh sehingga kulit kehilangan kalor.',question:'Apakah keringat yang menetes tanpa menguap memberi efek pendinginan yang sama?',concept:'Penguapan keringat menyerap kalor laten. Banyaknya pendinginan bergantung pada keringat yang menguap; udara lembap menghambat penguapan.',derivation:['Tubuh menghasilkan kalor dari metabolisme.','Keringat keluar melalui kelenjar kulit.','Ketika air menguap, energi panas dibutuhkan dan permukaan kulit dapat mendingin.'],assumption:'Model kualitatif; laju penguapan bergantung suhu, kelembapan, aliran udara, dan luas kulit.',controls:[C('air','Kondisi udara',[['dry','Lebih kering'],['humid','Sangat lembap']],'dry')],calc:o=>explain(o.air==='dry'?'Penguapan relatif lebih mudah':'Penguapan relatif terhambat','Pendinginan lebih efektif jika lebih banyak keringat benar-benar menguap.'),render:(o,t)=>svg(foreground('Uap air membawa energi dari permukaan kulit')+rect(111,206,535,71,'#f1b79a',23)+Array.from({length:8},(_,i)=>circ(165+i*58,202,8,'#77b5ce')).join('')+Array.from({length:o.air==='dry'?6:2},(_,i)=>arrow(180+i*75,182,180+i*75,112,'#73aeb4',3)).join('')+text(99,90,o.air==='dry'?'Udara kering: penguapan relatif cepat':'Udara lembap: penguapan lebih lambat','note')+text(280,298,'Permukaan kulit','note'),'Tetes keringat dan panah penguapan air dari kulit')});

add('flower',{module:4,name:'Dari bunga ke biji dan buah',emoji:'🌸',tag:'Perkembangbiakan tumbuhan',observe:'Pada tumbuhan berbunga, bakal biji biasanya berkembang menjadi biji setelah pembuahan. Ovarium (bakal buah) umumnya berkembang menjadi buah.',question:'Bakal biji dan bakal buah menghasilkan struktur yang sama?',concept:'Bakal biji → biji, sedangkan bakal buah (ovarium) → buah. Buah melindungi dan membantu penyebaran biji.',derivation:['Serbuk sari yang sesuai dapat menumbuhkan buluh serbuk sari menuju bakal biji.','Pembuahan berlangsung pada bakal biji.','Setelah perkembangan, bakal biji menjadi biji dan ovarium menjadi buah.'],assumption:'Perkembangan umum tumbuhan berbunga; banyak variasi morfologi buah serta buah tambahan.',controls:[C('stage','Amati bagian',[['flower','Bunga sebelum perkembangan buah'],['fruit','Buah dan biji']],'flower')],calc:o=>explain(o.stage==='flower'?'Bakal biji berada dalam bakal buah':'Biji berada di dalam buah','Pembedaan istilah bakal biji dan bakal buah penting untuk soal struktur bunga.'),render:(o,t)=>svg(foreground('Dua bagian punya hasil perkembangan berbeda')+(o.stage==='flower'?circ(270,156,75,'#e9a9b7')+circ(270,156,44,'#f7d79c')+circ(270,156,15,'#c88e59')+text(406,132,'Bakal buah (ovarium)','note')+text(406,168,'Bakal biji di dalamnya','tiny'):circ(270,156,91,'#e8b270','#c58c52',4)+circ(270,156,21,'#9f7757')+text(414,132,'Buah','note')+text(414,168,'Biji','note'))+arrow(178,278,357,278,'#8bbd91',4)+text(379,284,o.stage==='flower'?'Setelah pembuahan →':'Perkembangan bagian bunga','tiny'),'Perkembangan bakal biji menjadi biji dan bakal buah menjadi buah')});

add('stomata',{module:4,name:'Stomata: pintu gas dan uap air',emoji:'🍃',tag:'Fisiologi tumbuhan',observe:'Stomata terbuka memudahkan masuknya CO₂ untuk fotosintesis, sekaligus menjadi jalan keluarnya uap air. Saat menutup, kehilangan air berkurang tetapi pasokan CO₂ juga dapat berkurang.',question:'Apa konsekuensi yang mungkin timbul ketika stomata menutup pada siang hari?',concept:'Sel penjaga mengatur bukaan stomata melalui perubahan tekanan turgor. Ada pertukaran antara penghematan air dan pertukaran gas.',derivation:['CO₂ berdifusi ke daun terutama melalui stomata.','Air juga menguap dari jaringan daun dan keluar melalui stomata.','Saat stomata menutup, kehilangan uap air berkurang, tetapi masuknya CO₂ juga terbatas.'],assumption:'Gerak buka-tutup disederhanakan; fotosintesis juga dipengaruhi intensitas cahaya, suhu, dan faktor lain.',controls:[C('pore','Bukaan stomata',[['open','Terbuka'],['closed','Menutup']],'open')],calc:o=>explain(o.pore==='open'?'Pertukaran gas lebih mudah':'Transpirasi dan pasokan CO₂ cenderung berkurang','Stomata tidak berfungsi sebagai pompa; gas bergerak melalui difusi.'),render:(o,t)=>svg(foreground('Dua sel penjaga mengelilingi celah stomata')+`<ellipse cx="339" cy="168" rx="${o.pore==='open'?51:24}" ry="105" fill="#8bbd91" stroke="#5c936f" stroke-width="4"/>`+`<ellipse cx="425" cy="168" rx="${o.pore==='open'?51:24}" ry="105" fill="#8bbd91" stroke="#5c936f" stroke-width="4"/>`+rect(379,102,o.pore==='open'?8:2,128,'#e9f3ec',3)+arrow(190,151,o.pore==='open'?365:302,151,'#77a7ca',3)+arrow(o.pore==='open'?447:470,207,585,207,'#9cb6c8',3)+text(131,131,'CO₂ masuk','note')+text(526,242,'H₂O keluar','note')+text(279,307,o.pore==='open'?'Stomata terbuka':'Stomata menutup','note'),'Dua sel penjaga stomata dengan aliran CO2 masuk dan uap air keluar')});

add('atmosphere',{module:12,name:'Tempat sebagian besar cuaca terbentuk',emoji:'☁️',tag:'Atmosfer Bumi',observe:'Awan, hujan, dan kebanyakan gejala cuaca berlangsung di troposfer, lapisan terbawah atmosfer.',question:'Mengapa cuaca sehari-hari bukan terutama terjadi di stratosfer?',concept:'Troposfer mengandung sebagian besar massa udara dan uap air atmosfer; turbulensi dan proses pembentukan awan terjadi di lapisan ini.',derivation:['Permukaan Bumi memasok uap air melalui penguapan.','Udara yang naik dapat mendingin sehingga uap mengembun membentuk awan.','Proses itu umumnya berlangsung di troposfer.'],assumption:'Ketinggian batas lapisan berubah menurut lintang dan musim. Gambar sangat disederhanakan.',controls:[C('layer','Lapisan ditinjau',[['tropo','Troposfer'],['strato','Stratosfer']],'tropo')],calc:o=>explain(o.layer==='tropo'?'Sebagian besar cuaca: troposfer':'Stratosfer: berada di atas troposfer','Stratosfer mengandung sebagian besar ozon atmosfer; bukan lokasi utama hujan harian.'),render:(o,t)=>svg(foreground('Lapisan atmosfer · bukan perbandingan skala')+rect(75,173,615,108,o.layer==='tropo'?'#c8e9e7':'#ecf2e8',15)+rect(75,62,615,108,o.layer==='strato'?'#c8e9e7':'#ecf2e8',15)+text(110,105,'Stratosfer','note')+text(110,218,'Troposfer','note')+circ(500,217,23,'#fff6e8')+circ(529,212,32,'#fff6e8')+circ(550,221,21,'#fff6e8')+Array.from({length:4},(_,i)=>line(503+i*17,245,493+i*17,269,'#7db7d0',3)).join('')+text(76,312,'Permukaan Bumi','note'),'Dua lapisan atmosfer dengan awan dan hujan pada troposfer')});

add('tectonics',{module:12,name:'Lempeng bergerak dan menunjam',emoji:'🌋',tag:'Tektonik',observe:'Pada batas konvergen, satu lempeng dapat bergerak turun di bawah lempeng lain. Proses ini disebut subduksi.',question:'Mengapa zona subduksi sering terkait gempa dan beberapa jalur gunung api?',concept:'Gerak relatif lempeng menimbulkan deformasi dan patahan yang dapat menghasilkan gempa. Fluida dari lempeng menunjam dapat membantu pembentukan magma di mantel atas.',derivation:['Dua lempeng bergerak saling mendekat.','Salah satu lempeng dapat menunjam di bawah lempeng lain.','Tegangan batuan serta proses magmatik berkaitan dengan gempa dan aktivitas vulkanik.'],assumption:'Penampang ideal; tidak semua batas konvergen membentuk gunung api, dan proses pembentukan magma lebih kompleks.',controls:[C('motion','Jenis gerak batas lempeng',[['converge','Konvergen / saling mendekat'],['diverge','Divergen / saling menjauh']],'converge')],calc:o=>explain(o.motion==='converge'?'Konvergensi dapat menimbulkan subduksi':'Divergensi dapat membentuk kerak baru','Arah dan sifat lempeng menentukan tipe batas lempeng.'),render:(o,t)=>svg(foreground('Potongan permukaan Bumi')+rect(79,102,604,45,'#b9cfc1',5)+(o.motion==='converge'?`<path d="M89 145L391 145L608 281L654 281L419 167L89 167Z" fill="#a68f85"/>`+arrow(221,81,337,81,'#cb8568',4)+arrow(565,81,448,81,'#7a9dae',4)+text(447,230,'lempeng menunjam','tiny'):`<path d="M89 149L340 149L360 217L382 217L408 149L654 149L654 172L412 172L381 243L356 243L329 172L89 172Z" fill="#a68f85"/>`+arrow(337,81,221,81,'#cb8568',4)+arrow(448,81,565,81,'#7a9dae',4)+text(299,265,'bagian kerak dapat meregang','tiny'))+text(90,316,'Lempeng bergerak perlahan dalam skala waktu geologi','tiny'),'Perbandingan batas lempeng konvergen dengan subduksi dan divergen')});

add('tides',{module:12,name:'Bulan, Matahari, dan pasang laut',emoji:'🌊',tag:'Gravitasi',observe:'Tarik gravitasi Bulan dan Matahari berperan dalam pasang. Saat Bumi, Bulan, dan Matahari hampir segaris, perbedaan gaya pasang dapat saling menguatkan.',question:'Apakah pasang purnama berarti hanya terjadi ketika gerhana?',concept:'Pasang purnama (spring tide) sekitar bulan baru dan purnama tidak mensyaratkan gerhana; gerhana memerlukan kesegarisaan lebih tepat serta kemiringan orbit yang sesuai.',derivation:['Tarik gravitasi tidak sama persis pada seluruh bagian Bumi.','Perbedaan efek gravitasi terutama Bulan dan juga Matahari menghasilkan pola gaya pasang.','Saat posisi relatif hampir segaris, rentang pasang-surut cenderung lebih besar; ketika membentuk sudut hampir siku-siku, cenderung lebih kecil.'],assumption:'Sketsa ilustratif posisi benda; pasang lokal dipengaruhi pantai, bentuk laut, cuaca, dan waktu respons.',controls:[C('phase','Posisi relatif',[['aligned','Bulan baru / purnama (segaris)'],['quarter','Kuartir (sudut hampir 90°)']],'aligned')],calc:o=>explain(o.phase==='aligned'?'Pasang purnama: rentang cenderung lebih besar':'Pasang perbani: rentang cenderung lebih kecil','Gerhana bukan syarat terjadinya pasang purnama.'),render:(o,t)=>svg(foreground('Hubungan posisi, bukan jarak berskala')+circ(105,176,67,'#f6d47b')+circ(390,176,74,'#7faec9')+circ(o.phase==='aligned'?604:390,o.phase==='aligned'?176:49,28,'#c8ccd2')+text(62,274,'Matahari','note')+text(361,274,'Bumi','note')+text(o.phase==='aligned'?576:407,o.phase==='aligned'?236:54,'Bulan','tiny')+text(127,66,o.phase==='aligned'?'Gaya pasang cenderung saling menguatkan':'Gaya pasang cenderung sebagian mengimbangi','note'),'Posisi Bumi Matahari dan Bulan pada pasang purnama serta pasang perbani')});

add('geothermal',{module:12,name:'Geyser dan air panas bumi',emoji:'♨️',tag:'Energi geotermal',observe:'Air bawah tanah dapat dipanaskan oleh batuan panas. Dalam sistem yang sesuai, air dan uap tertekan keluar berkala sebagai geyser.',question:'Mengapa tidak semua sumber air panas memancar sebagai geyser?',concept:'Geyser membutuhkan kombinasi suplai air, sumber panas, sistem rekahan/saluran, dan geometri penahan tekanan yang sesuai.',derivation:['Air masuk melalui celah batuan di bawah permukaan.','Air dipanaskan dan tekanan terbentuk pada ruang atau saluran tertentu.','Ketika kondisi tekanan dan didih tercapai, air panas dan uap dapat menyembur.'],assumption:'Siklus geyser adalah ilustrasi tahap, bukan prediksi waktu/tekanan letusan nyata.',controls:[C('stage','Peristiwa',[['heat','Air dipanaskan di bawah tanah'],['erupt','Air panas/uap menyembur']],'heat')],calc:o=>explain(o.stage==='heat'?'Air tersimpan dan dipanaskan':'Air/uap dapat keluar saat kondisi memungkinkan','Gunakan contoh geyser untuk membedakan energi panas bumi dari proses pembakaran.'),render:(o,t)=>svg(foreground('Penampang saluran air panas alami')+rect(52,140,655,169,'#c9ab8e',0)+`<path d="M372 150L372 227Q372 256 323 265Q277 277 275 304" stroke="#6bafce" stroke-width="18" fill="none"/>`+(o.stage==='erupt'?Array.from({length:5},(_,i)=>arrow(369+i*8,135,359+i*10,47,'#7bc0d2',3)).join(''):circ(278,284,22,'#90cddd'))+text(456,252,'Batuan panas','note')+text(409,94,o.stage==='erupt'?'Air panas dan uap naik':'Air memanas di bawah permukaan','note'),'Penampang sumber air panas bawah tanah dan semburan geyser')});

add('rainbow',{module:9,name:'Bagaimana cahaya putih menjadi pelangi?',emoji:'🌈',tag:'Cahaya',observe:'Cahaya Matahari yang masuk ke tetes hujan mengalami pembiasan, pemantulan dalam, dan dispersi sehingga warna keluar pada arah berbeda.',question:'Apakah pelangi hanya disebabkan pemantulan tanpa pembiasan?',concept:'Pelangi primer melibatkan pembiasan saat masuk dan keluar tetes, dispersi warna, serta sekali pemantulan internal.',derivation:['Indeks bias air sedikit berbeda untuk berbagai panjang gelombang cahaya tampak.','Warna dibelokkan dengan sudut berbeda saat masuk tetes dan kembali saat keluar.','Banyak tetes pada arah pengamatan yang tepat membentuk pola pelangi.'],assumption:'Skema satu tetes hujan tidak berskala dan hanya menggambarkan proses, bukan geometri pengamatan pelangi secara lengkap.',controls:[C('stage','Amati proses',[['enter','Masuk: pembiasan'],['inside','Di dalam: pemantulan'],['exit','Keluar: dispersi warna']],'enter')],calc:o=>explain(({enter:'Cahaya putih dibias saat masuk',inside:'Sebagian cahaya memantul di dalam',exit:'Warna keluar ke arah berbeda'})[o.stage],'Dispersi muncul karena indeks bias bergantung pada panjang gelombang cahaya.'),render:(o,t)=>svg(foreground('Satu tetes hujan · skema tidak berskala')+circ(411,173,125,'#d5edf7','#92c5dc',5)+arrow(101,67,335,128,'#e4c88b',5)+(o.stage==='inside'?arrow(340,133,467,242,'#df986b',5):o.stage==='exit'?['#e79a82','#f2bf78','#e8d87d','#8ebaa0','#89abdb','#b49ac9'].map((co,i)=>arrow(442,242,580+i*6,250+i*10,co,4)).join(''):arrow(336,132,465,242,'#df986b',4))+text(79,49,'cahaya putih','note')+text(537,74,'tetes air','note')+text(89,318,'Pembiasan + pemantulan internal + dispersi','note'),'Sinar putih dibias masuk tetes air dan dipisahkan menjadi warna')});

add('myopia',{module:9,name:'Mengapa mata minus perlu lensa cekung?',emoji:'👓',tag:'Optik mata',observe:'Pada miopi, berkas dari objek jauh difokuskan terlalu depan retina saat mata tanpa koreksi. Lensa divergen (cekung) membantu menggeser titik fokus ke retina.',question:'Apakah miopi umumnya dikoreksi dengan lensa cembung atau cekung?',concept:'Lensa cekung dengan daya negatif menyebarkan sinar datang sebelum masuk mata sehingga fokus sistem mata dapat jatuh tepat pada retina.',derivation:['Objek jauh mengirim berkas hampir sejajar ke mata.','Pada mata miopi tanpa koreksi, bayangan jatuh di depan retina.','Lensa cekung mendivergensikan sinar sehingga setelah dibiaskan mata, fokus dapat bergeser ke retina.'],assumption:'Model satu dimensi disederhanakan; besaran koreksi nyata ditentukan pemeriksaan refraksi individu.',controls:[C('lens','Kondisi',[['off','Tanpa lensa koreksi'],['on','Memakai lensa cekung']],'off')],calc:o=>explain(o.lens==='on'?'Fokus terbantu menuju retina':'Fokus mata miopi jatuh di depan retina','Koreksi miopi menggunakan lensa divergen/cekung (daya negatif).'),render:(o,t)=>svg(foreground('Potongan mata · skema sinar, tidak berskala')+circ(521,172,127,'#e8d8c3','#c6b6a2',5)+line(642,74,642,269,'#bf9c90',5)+`<path d="M445 94Q490 172 445 250" stroke="#8dbec3" stroke-width="10" fill="none"/>`+(o.lens==='on'?`<path d="M250 79Q277 172 250 266" stroke="#8cafe1" stroke-width="7" fill="none"/>`:'')+arrow(102,115,445,133,'#e4a36e',3)+arrow(102,228,445,211,'#e4a36e',3)+arrow(446,133,o.lens==='on'?642:578,172,'#d59d79',3)+arrow(446,211,o.lens==='on'?642:578,172,'#d59d79',3)+text(102,67,o.lens==='on'?'Lensa cekung sebelum mata':'Tanpa lensa koreksi','note')+text(622,305,'retina','note'),'Mata miopi menunjukkan fokus cahaya di depan retina dan setelah lensa cekung')});

add('competition',{module:13,name:'Dua spesies berebut satu sumber',emoji:'🐦',tag:'Interaksi ekologis',observe:'Ketika dua populasi menggunakan sumber daya yang terbatas, masing-masing dapat mengalami pengurangan akses. Itu disebut kompetisi.',question:'Jika dua jenis burung memakan serangga yang sama dalam satu tempat, interaksi apa yang mungkin terjadi?',concept:'Kompetisi antarpopulasi dapat timbul bila kebutuhan sumber daya saling tumpang tindih dan ketersediaan sumber terbatas.',derivation:['Identifikasi jenis sumber daya yang diperlukan kedua spesies.','Periksa apakah sumber itu terbatas dan digunakan bersama.','Penggunaan bersama dapat menimbulkan kompetisi, berbeda dari predasi atau mutualisme.'],assumption:'Diagram tidak memprediksi siapa yang menang atau jumlah populasi tanpa data lapangan.',controls:[C('resource','Ketersediaan serangga',[['few','Terbatas'],['plenty','Melimpah']],'few')],calc:o=>explain(o.resource==='few'?'Kompetisi berpotensi lebih kuat':'Tekanan kompetisi dapat berkurang','Keberadaan dua spesies di habitat sama belum otomatis membuktikan kompetisi tanpa bukti sumber terbatas.'),render:(o,t)=>svg(foreground('Dua burung memakai sumber makanan yang sama')+circ(185,165,54,'#87becb')+circ(562,165,54,'#d0b694')+text(151,172,'A','note')+text(539,171,'B','note')+Array.from({length:o.resource==='few'?4:14},(_,i)=>circ(328+(i*43)%139,118+(i*36)%136,7,'#a27e4f')).join('')+arrow(238,167,324,167,'#94b6a0',3)+arrow(514,167,472,167,'#ba987f',3)+text(267,69,'Sumber makanan sama','note'),'Dua populasi mengakses persediaan serangga terbatas')});

add('plastic',{module:13,name:'Dari sampah plastik ke sungai',emoji:'🧴',tag:'Pencemaran',observe:'Plastik yang dibuang tidak pada tempatnya dapat terbawa aliran hujan dari darat ke saluran drainase dan sungai, kemudian menjadi fragmen kecil.',question:'Tindakan hulu apa yang paling langsung mengurangi plastik mencapai sungai?',concept:'Pencegahan di sumber melalui pengurangan plastik sekali pakai, penanganan dan pengelolaan sampah mengurangi beban pencemaran sungai.',derivation:['Sampah terbuka dapat terbawa aliran limpasan.','Drainase menghubungkan kawasan darat dengan sungai.','Mengurangi sampah dan menangkap/mengelolanya sebelum masuk perairan menekan beban pencemar.'],assumption:'Gambar menunjukkan jalur sederhana, bukan model hidrologi kuantitatif.',controls:[C('waste','Pengelolaan sampah',[['poor','Dibuang terbuka'],['good','Dikelola sebelum masuk sungai']],'poor')],calc:o=>explain(o.waste==='poor'?'Plastik berpotensi terbawa ke sungai':'Sumber plastik yang masuk sungai berkurang','Pencegahan di sumber perlu disertai pengumpulan dan pengelolaan sampah.'),render:(o,t)=>svg(foreground('Dari darat, melewati drainase, ke sungai')+rect(71,163,265,114,'#e0c3a2',8)+rect(337,164,352,116,'#c3e7ee',8)+Array.from({length:o.waste==='poor'?8:2},(_,i)=>rect(136+(i*47)%480,165+(i*29)%86,16,8,'#d69088',3)).join('')+arrow(276,210,453,210,'#5b9db0',5)+text(144,140,'Permukiman','note')+text(473,141,'Sungai','note')+text(147,307,o.waste==='poor'?'Sampah terbuka → terbawa aliran':'Sampah dikelola → kebocoran berkurang','note'),'Sampah plastik terbawa limpasan menuju sungai dan pencegahan dari sumber')});

const byMath={efficiency:'efficiency',ohm:'ohm',frequency:'oscillation',speed:'speed',pulley:'pulley',density:'density',newton:'newton',heat:'heat',pascal:'pascal',hydro:'hydro',lever:'lever',parallel:'parallel',kinetic:'kinetic',series:'series',wave:'wave',reflect:'reflection',genetics:'genetics',potential:'potential',incline:'incline'};
const moduleDefaults={1:'scientific',2:'classification',3:'circulation',4:'tropism',5:'cell',6:'lever',7:'density',8:'ohm',9:'wave',10:'heat',11:'efficiency',12:'orbit',13:'foodchain',14:'immune'};
function forQuestion(q){
 if(q.math&&byMath[q.math.symbol])return byMath[q.math.symbol];
 const z=(q.question+' '+q.conceptName).toLowerCase();
 const has=re=>re.test(z);
 switch(+q.modul){
  case 1:return 'scientific';
  case 2:return has(/genetik|varietas|ekosistem|bioma|keanekaragaman/)?'biodiversity':'classification';
  case 3:return has(/nefron|ginjal|urine/)?'kidney':has(/berkeringat|keringat|suhu tubuh naik/)?'thermoregulation':has(/amilase|pencernaan|enzim|lambung|usus|pati|makanan|empedu|lipase|selulosa|ruminansia/)?'digestion':has(/refleks|sumsum|saraf/)?'reflex':has(/pembuluh darah|arteri pulmonalis|vena pulmonalis/)?'circulation':has(/pernapasan|napas|insang|alveolus|oksigen|pertukaran gas/)?'gasexchange':'circulation';
  case 4:return has(/nasti|putri malu|menutup.*sentuh/)?'nasti':has(/bakal biji|bakal buah|pembuahan/)?'flower':has(/stomata|transpirasi|kutikula|daun kecil|duri.*kutikula/)?'stomata':has(/xilem|floem|transport|mengangkut|angkut|akar menyerap|penyerapan akar|kambium/)?'vascular':has(/fotosintesis|karbon dioksida|klorofil|pati/)?'photosynthesis':'tropism';
  case 5:return has(/pembelahan|mitosis|meiosis|kromosom.*anak/)?'mitosis':has(/virus/)?'virus':'cell';
  case 6:return 'lever';
  case 7:return has(/mencair|menguap|membeku|menyublim|mengembun|kondensasi|wujud/)?'states':has(/hidrolik/)?'pascal':has(/hidrostatis|kedalaman/)?'hydro':'density';
  case 8:return has(/magnet|kompas|kumparan|elektromagnet|paku besi/)?'magnet':'ohm';
  case 9:return has(/pelangi|warna.*hujan/)?'rainbow':has(/miopi|mata minus|lensa cekung/)?'myopia':has(/lensa|kaca pembesar|kamera/)?'lens':has(/cermin cembung|tikungan|bidang pandang/)?'convexmirror':has(/cahaya.*(udara ke kaca|air ke udara)|arah sinar bias|pembiasan|fatamorgana|dasar kolam|bias/)?'refraction':has(/pemantulan|pantul|cermin/)?'reflection':has(/getaran|bandul|periode|senar bergetar/)?'oscillation':'wave';
  case 10:return has(/konduksi|sendok logam/)?'conduction':has(/konveksi|aliran naik-turun/)?'convection':has(/radiasi|matahari|ruang hampa/)?'radiation':'heat';
  case 11:return 'efficiency';
  case 12:return has(/pasang air laut|pasang-surut|pasang maksimum/)?'tides':has(/troposfer|stratosfer|lapisan atmosfer|cuaca/)?'atmosphere':has(/lempeng tektonik|menunjam|subduksi/)?'tectonics':has(/geotermal|semburan air panas|geyser/)?'geothermal':has(/magma|lava|gunung api|letusan/)?'volcano':has(/gerhana|bayangan inti/)?'eclipse':has(/seismograf|gempa|batuan/)?'seismograph':'orbit';
  case 13:return has(/sampah plastik|plastik.*sungai/)?'plastic':has(/sumber serangga|kompetisi|sumber daya.*terbatas/)?'competition':has(/konservasi|spesies asing|invasif|endemik|fragmentasi|habitat|cagar|bank benih|pelestarian/)?'conservation':has(/mutualisme|parasitisme|komensalisme|predasi|lebah|anggrek|benalu/)?'symbiosis':'foodchain';
  case 14:return has(/rabies|gigitan|luka hewan/)?'rabies':has(/filter|filtrasi|saringan|berpori/)?'waterfilter':has(/panel surya|fotovoltaik/)?'solar':has(/bioremediasi|menguraikan polutan/)?'bioremediation':has(/tercemar tinja|penyakit.*air minum/)?'waterborne':has(/demam berdarah|vektor penyakit|insektisida/)?'vector':has(/pm2[.,]5|kualitas udara|masker partikulat|polusi asap/)?'airquality':has(/dna barcoding|barcode dna/)?'barcoding':has(/mencuci tangan|sabun/)?'handwash':has(/digester|biogas|anaerob.*gas/)?'biogas':has(/insulin.*bakteri|rekayasa genetika/)?'bioengineering':has(/yoghurt|yogurt/)?'yogurt':has(/fermentasi|ragi|roti/)?'fermentation':has(/kamera|drone|multispektral|vegetasi|sensor|citra/)?'sensor':has(/antibiotik|resisten|bakteri|virus|flu/)?'antibiotic':has(/vaksin|imun|memori|antibodi/)?'immune':'handwash';
  default:return moduleDefaults[q.modul]||'scientific';
 }
}

window.KLUB_MODELS=M;window.KLUB_MODEL_FOR_QUESTION=forQuestion;window.KLUB_MODEL_MATH=byMath;window.KLUB_MODEL_DEFAULTS=moduleDefaults;
})();
